\maketitle

\begin{abstract}
   In distributed stochastic optimization, where parallel and asynchronous methods are employed, we establish optimal time complexities under virtually any computation behavior of workers/devices/CPUs/GPUs, capturing potential disconnections due to hardware and network delays, time-varying computation powers, and any possible fluctuations and trends of computation speeds. These real-world scenarios are formalized by our new \emph{universal computation model}. Leveraging this model and new proof techniques, we discover tight lower bounds that apply to virtually all synchronous and asynchronous methods, including \algname{Minibatch SGD}, \algname{Asynchronous SGD} \citep{recht2011hogwild}, and \algname{Picky SGD} \citep{cohen2021asynchronous}. We show that these lower bounds, up to constant factors, are matched by the optimal \algname{Rennala SGD} and \algname{Malenia SGD} methods \citep{tyurin2023optimal}.
\end{abstract}

\section{Introduction}
\label{sec:introduction}

Optimization is one of the main workhorses in machine learning (ML), data science (DS), and federated learning (FL) \citep{bottou2018optimization, kairouz2021advances}. These fields rely on stochastic optimization methods, with notable examples including the stochastic gradient descent method (\algname{SGD}) \citep{robbins1951stochastic} and \algname{ADAM} \citep{kingma2014adam}, which are considered to be the de facto choices for solving large-scale optimization problems \citep{schmidt2021descending}. Due to the computational demands of modern functions, the size of datasets, and the need for data privacy, parallelization and distribution are essential for building efficient systems \citep{kairouz2021advances, mayer2020scalable}. However, it brings many challenges, including \emph{computation heterogeneity}: many workers/CPUs/GPUs/phones work in parallel but with varying computation speeds, fluctuating performance over time, and potential disconnections due to hardware and network delays \citep{li2020federateda}.

\subsection{Problem setup}

% Before we continue discussing \emph{computation heterogeneity}, let us formalize unconstrained smooth optimization problems:
Unconstrained smooth optimization problems that arise in ML, DS, and FL are described by
\begin{align}
\label{eq:main_problem}
\textstyle \min \limits_{x \in \R^d} f(x),
\end{align}
where $f\,:\,\R^d \rightarrow \R$ with the following standard assumptions:

\begin{assumption}
  \label{ass:lipschitz_constant}
$f$ is differentiable \& $L$--smooth, i.e., $\norm{\nabla f(x) - \nabla f(y)} \leq L \norm{x - y}$, $\forall x, y \in \R^d.$
\end{assumption}

\begin{assumption}
  \label{ass:lower_bound}
  There exist $f^* \in \R$ such that $f(x) \geq f^*$ for all $x \in \R^d$.
\end{assumption}
In the nonconvex world, we want to find an $\varepsilon$--stationary point, a (random) vector $\bar{x} \in \R^d$ such that ${\rm \mathbb{E}}[\|\nabla f(\bar{x})\|^2] \leq \varepsilon,$ since, in general, it is intractable to find a global minimum in the nonconvex setting \citep{nemirovskij1983problem,murty1985some}. We analyze convex functions in Section~\ref{sec:convex}.
% Our goal is to investigate the setting where $n$ workers/devices work in parallel and have access to stochastic gradients.

We consider a problem where workers \emph{do not} have access to the gradients of the function $f.$ Instead, they can only calculate stochastic gradients. Such a problem arises when the computation cost of an exact gradient is huge or even infeasible due to batch normalization \citep{ioffe2015batch}, dropout, random data augmentation, and many other handcrafted and naturally occurring noise sources that do not allow to calculate a gradient \citep{goodfellow2016deep}.

Assume that $n$ workers work asynchronously in parallel and calculate stochastic gradients. We focus on two setups: \\
\textbf{Homogeneous setup.} For all $i \in [n],$ worker $i$ has access to an unbiased stochastic gradients $\nabla f(x;\xi)$ with $\sigma^2$-variance-bounded variances, where $\xi$ is a random variable from some distribution $\mathcal{D}$ on $\mathbb{S}_{\xi}.$ In ML and FL, this would mean that all workers have access to the \emph{same data}.

\begin{assumption}[Homogeneous setup]
  \label{ass:stochastic_variance_bounded}
  For all $i \in [n],$ worker $i$ can only calculate $\nabla f(x;\xi)$ and ${\rm \mathbb{E}}_{\xi}[\nabla f(x;\xi)] = \nabla f(x)$ and 
    ${\rm \mathbb{E}}_{\xi}[\|\nabla f(x;\xi) - \nabla f(x)\|^2] \leq \sigma^2$ for all $x \in \R^d,$ where $\sigma^2 \geq 0.$
\end{assumption}

\textbf{Heterogeneous setup.} 
Unlike the previous setup, we assume that 
% \begin{align*}
  $\textstyle f(x) = \frac{1}{n} \sum_{i = 1}^n f_i(x)$
% \end{align*}
in this setting,
where $f_i\,:\,\R^d \rightarrow \R$ for all $i \in [n],$ and worker $i$ can only access stochastic gradients $\nabla f_i(x;\xi_i)$ of the local function $f_i,$ where $\xi_i$ is a random variable from some distribution $\mathcal{D}_i$ on $\mathbb{S}_{\xi}.$ In ML and FL, this would mean that all workers have access to \emph{different data}.
\begin{assumption}[Heterogeneous setup]
  \label{ass:stochastic_variance_bounded_heter}
  For all $i \in [n],$ worker $i$ can only calculate $\nabla f_i(x;\xi_i),$ and ${\rm \mathbb{E}}_{\xi_i}[\nabla f_i(x;\xi_i)] = \nabla f_i(x)$ and 
    ${\rm \mathbb{E}}_{\xi_i}[\|\nabla f_i(x;\xi_i) - \nabla f_i(x)\|^2] \leq \sigma^2$ for all $x \in \R^d,$ where $\sigma^2 \geq 0.$
\end{assumption}

\subsection{Related Work}
\textbf{Oracle complexity with \emph{one worker}.} The optimal (dimension-free) \emph{oracle complexity}, \# of stochastic gradient calls, and an optimal method are well-known in the homogeneous and heterogeneous setups. In particular, \citet{arjevani2022lower,carmon2020lower} showed that the optimal oracle complexity is
% \begin{align*}
  $\textstyle \operatorname{O}\left(\nicefrac{L \Delta}{\varepsilon} + \nicefrac{\sigma^2 L \Delta}{\varepsilon^2}\right)$
% \end{align*}
achieved by \algname{SGD}, i.e., $x^{k+1} = x^{k} - \gamma \nabla f(x^k; \xi^k),$ where $\xi^k$ are i.i.d. random samples, $\Delta \eqdef f(x^0) - f^*,$ $x^0 \in \R^d$ is a starting point, $\gamma = \Theta\left(\min\{\nicefrac{1}{L},\nicefrac{\varepsilon}{L \sigma^2}\}\right)$ is a step size. 
% If we additionally assume that the computation time of one stochastic gradient is $\tau_1$ seconds, then the optimal \emph{time complexity} is 
% \begin{align*}
%   \textstyle \operatorname{O}\left(\tau_1 \left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{\varepsilon^2}\right)\right)
% \end{align*}
% seconds.

\textbf{Oracle complexities with $n$ \emph{workers}.} There were several approaches, e.g., \citep{scaman2017optimal,arjevani2020tight,lu2021optimal}, to generalize the classical oracle complexity \citep{nemirovskij1983problem, arjevani2022lower} to the parallel setup with $n$ workers. In the homogeneous convex setup, the most relevant to our setup work \citep{woodworth2018graph}, using the \emph{graph-based oracle model}, obtained the tight oracle complexities for several parallel setups. The heterogeneous setup with the local smoothness assumption was addressed in \citep{arjevani2015communication,hanzely2020lower,lu2021optimal}.

The listed works address key questions in parallel optimization by establishing lower bounds and developing methods to achieve them. However, the assumptions regarding the computation processes are overly idealistic, as they assume stable, unchanging, and equal computation speeds for all workers. They fail to capture practical scenarios such as partial participation, random outages, computation heterogeneity (some workers being faster than others), communication heterogeneity (some workers sending vectors faster than others), and changing computation performance over time. \emph{It is unclear if the optimal methods for their lower bounds will maintain optimality in more realistic computation scenarios.}

\textbf{Time complexities with bounded computation times.}
Instead of using \emph{oracle complexities}, another way to compare algorithms is to use \emph{time complexities.} Using this paradigm, \citet{mishchenko2022asynchronous,koloskova2022sharper} showed that the celebrated \algname{Asynchronous SGD} method \citep{recht2011hogwild,dean2012large} with the proposer step sizes can provably improve \algname{Minibatch SGD} in the homogeneous setup. Assume for now that worker $i$ requires at most $\tau_i$ seconds to calculate one stochastic gradient for all $i \in [n].$
\algname{Minibatch SGD} is the iterative process $x^{k+1} = x^{k} - \nicefrac{\gamma }{n} \sum_{i=1}^n \nabla f(x^k; \xi^k_i),$ where $\gamma$ is a stepsize, $\xi^k_i$ are i.i.d. samples, and $\nabla f(x^k; \xi^k_i)$ are calculated in parallel. This method converges after $\operatorname{O}\left(\nicefrac{L \Delta}{\varepsilon} + \nicefrac{\sigma^2 L \Delta}{n \varepsilon^2}\right)$ iterations \citep{cotter2011better, goyal2017accurate, gower2019sgd} and after 
\begin{align}
    \label{eq:mini_batch_compl}
    \textstyle \operatorname{O}\left(\max\limits_{i \in [n]} \tau_i \times \left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{n \varepsilon^2}\right)\right)
\end{align} seconds because this method waits for the slowest worker with the time $\max_{i \in [n]} \tau_i.$ Using \algname{Asynchronous SGD}, the time complexity \eqref{eq:mini_batch_compl} can be improved to 
\begin{align}
  \label{eq:async_sgd_complexity}
  \squeeze
  \textstyle \operatorname{O}\left(\left(\frac{1}{n} \sum \limits_{i=1}^n \frac{1}{\tau_i}\right)^{-1}\left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{n \varepsilon^2}\right)\right),
\end{align}
where the dependence on the processing times is harmonic \citep{mishchenko2022asynchronous}. An alternative method that also achieves this time complexity is \algname{Picky SGD} \citep{cohen2021asynchronous}.

Subsequently, \citet{tyurin2023optimal} formalized the notion of time complexity using the \emph{time oracle protocol}, and under the assumption that worker $i$ requires at most $\tau_i$ seconds to calculate one stochastic gradient for all $i \in [n],$ proved that the time complexity lower bound is
\begin{align}
  \label{eq:orig_rennala}
  \textstyle \Theta\left(\min\limits_{m \in [n]} \left[\left(\frac{1}{m} \sum\limits_{i=1}^{m} \frac{1}{\tau_{\pi_i}}\right)^{-1} \left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{m \varepsilon^2}\right)\right]\right)
\end{align}
seconds in the homogeneous setup, where $\pi$ is a permutation that sorts $\tau_i:$ $\tau_{\pi_1} \leq \dots \leq \tau_{\pi_n}.$ Moreover, they developed a new method, \algname{Rennala SGD}, that achieves the lower bound in the homogeneous setup. Under the bounded computation and communication assumptions, \citet{tyurin2024shadowheart,tyurin2024optimal} provided optimal time complexities in a setup where the communication time between the workers cannot be ignored.

