\begin{restatable}{example}{EXAMPLERANDOM} [``Random'' Outages]
  \label{ex:random}
  Assume that 
  \begin{align}
    \label{eq:oWZYM}
    \textstyle v_i(t) = 
    \begin{cases}
      v, & t \in \bigcup\limits_{j = 1}^{\infty} [k_i (j - 1), (k_i (j - 1) + 1)] \\
      0, & \textnormal{otherwise},
    \end{cases},
  \end{align} $v > 0,$ $k_i \in \N,$ and $h_i > 0$ for all $i \in [n].$ 
