Unlike \eqref{eq:homog_compl} where the dependencies on $\{V_i\}$ are \emph{mean-like}, the dependencies in \eqref{eq:iTLiJe} are \emph{harmonic-like}. Since the heterogeneous setting is more general and complicated, this leads to worse guarantees. Looking ahead, up to logarithmic and constants factors, the obtained lower bound is tight and attained by \algname{Malenia SGD} \citep{tyurin2023optimal} (see Section~\ref{sec:malenia}). 

We asked ourselves if getting a tight lower bound without the logarithmic terms is possible. The answer is affirmative, but instead of taking one group of predefined worst-case deterministic functions $\{f_i\}$, the following construction samples random functions $\{f_i\}$.
% and we also take the expectation over the emerging randomness. 
The fact that the functions $\{f_i\}_{i=1}^n$ are random helps to prove a tight lower bound (the main difference between the theorems is highlighted in \textbf{bold}). This lower bound is fundamental and can not be bypassed by any parallel and asynchronous method \citep{zheng2017asynchronous,gu2021fast,mishchenko2022asynchronous,islamov2024asgrad}. We provide informal and formal versions of the theorem:

\begin{theorem*}[Informal Formulation of Theorem~\ref{theorem:random_lower_bound_heter_random}]
  Let Assumptions~\ref{ass:lipschitz_constant}, \ref{ass:lower_bound}, \ref{ass:stochastic_variance_bounded_heter}, and \ref{ass:speed} hold. It is impossible to converge faster than $\nicefrac{1}{2} \times \underline{t}_{\ceil{c_1 \times \frac{L \Delta}{\varepsilon}}}$ seconds, where the sequence $\{\underline{t}_k\}$ is defined in \eqref{eq:iTLiJe_random} and $c_1$ is a universal constant.
\end{theorem*}

\begin{restatable}{theorem}{RANDOMLOWERBOUNDFULLHETERRANDOM}
  \label{theorem:random_lower_bound_heter_random}
  Consider Protocol~\ref{alg:time_multiple_oracle_protocol}. We take computation powers $\{v_i\}$ such that Assumption~\ref{ass:speed} holds, and fix $L, \Delta, \varepsilon > 0$ and $\sigma^2 \geq 0$ that satisfy the inequality $\varepsilon < c' L \Delta$. For any algorithm $A \in \cA_{\textnormal{zr}},$ \textbf{we sample $\{f_i\}_{i=1}^n$ from some distribution of functions}, where the function $f = \frac{1}{n} \sum_{i=1}^n f_i$ satisfies Assumptions~\ref{ass:lipschitz_constant}, \ref{ass:lower_bound} and $f(0) - f^* \leq \Delta$ deterministically, and there exist stochastic gradient mappings $\{g_i\}_{i=1}^{n}$ in \eqref{eq:oracle_inside_random_heter}, which satisfy Assumption~\ref{ass:stochastic_variance_bounded_heter}, 
  % i.e., $\ExpSub{\xi_j}{g_i(s_x; \xi_j, t)} = \nabla f_i(s_x)$ and ${\mathbb{E}_{\xi_j}}[\norm{g_i(s_x; \xi_j, t) - \nabla f_i(s_x)}^2] \leq \sigma^2$ \textbf{for all possible queries $s_x \in \R^d$ of $A$}, for all $j \geq 1,$ and $t \geq 0,$
  i.e., $\ExpSub{\xi}{g_i(s_x; \xi, t)} = \nabla f_i(s_x)$ and ${\mathbb{E}_{\xi}}[\norm{g_i(s_x; \xi, t) - \nabla f_i(s_x)}^2] \leq \sigma^2$ for all $s_x \in \R^d, i \in [n],$ and $t \geq 0,$
  such that ${\mathbb{E}}\big[\inf\limits_{k \in S_t} \norm{\nabla f(x^k)}^2\big] > \varepsilon$ holds\footnote{We take the expectation over all randomness.}, 
  where $S_t \eqdef \left\{k \in \N_0 \,|\,t^k \leq t\right\},$
  \begin{align*}
    \textstyle t = \frac{1}{2} \underline{t}_{\flr{c_1 \times \frac{L \Delta}{\varepsilon}}}
  \end{align*}
  and 
  \begin{align}
    \label{eq:iTLiJe_random}
    \textstyle \underline{t}_{k} \eqdef \min\left\{t \geq 0 \,:\, \left(\frac{1}{n}\sum_{i=1}^n \flr{c_3 \times \left(V_{i}\left(t\right) - V_{i} (\underline{t}_{k - 1})\right)}^{-1}\right)^{-1} \geq \max\left\{c_2 \times \frac{\sigma^2}{n \varepsilon}, 1\right\} \right\}
  \end{align}
  for all $k \geq 1$ $(\underline{t}_{0} \equiv 0)$. The quantities $c', c_1,$ $c_2,$ and $c_3$ are universal constants. The sequences $x^k$ and $t^k$ are defined in Protocol~\ref{alg:time_multiple_oracle_protocol}.
\end{restatable}

\subsection{Optimal method}
\label{sec:malenia}

The obtained lower bound is tight since it is matched by \algname{Malenia SGD} \citep{tyurin2023optimal}. This method is closely related to \algname{Rennala SGD} with a similar structure, and mathematically, it is the vanilla \algname{SGD} method with a proper batch collection strategy (see Method~\ref{alg:alg_server}). However, essential algorithmic changes must be applied to make it work with heterogeneous functions. The following theorem was proved by \citet{tyurin2023optimal}.

\begin{restatable}{theorem}{THEOREMSGDHETROG}[\citep{tyurin2023optimal}]
  \label{thm:sgd_heterog}
  Let Assumptions~\ref{ass:lipschitz_constant}, \ref{ass:lower_bound}, and \ref{ass:stochastic_variance_bounded_heter} hold. We take take $S = \max\left\{\left\lceil\nicefrac{\sigma^2}{\varepsilon}\right\rceil, n\right\},$ and
  $\gamma = \min\left\{\frac{1}{L}, \frac{\varepsilon S}{2 L \sigma^2}\right\} = \Theta\left(1 / L\right)$ in Method~\ref{alg:alg_server_heterog},
  then after $K \geq 24 \Delta L / \varepsilon$
  iterations the method guarantees that $\frac{1}{K}\sum_{k=0}^{K-1}\Exp{\norm{\nabla f(x^k)}^2} \leq \varepsilon.$
\end{restatable}

This is a new theorem analyzing \algname{Malenia SGD} with the universal computation model:

\begin{restatable}{theorem}{THEOREMMAINSTATICTIMEHETER}
  \label{cor:max_time_params_heter}
  Consider the assumptions and the parameters from Theorem~\ref{thm:sgd_heterog}, plus Assumption~\ref{ass:speed}. Then Method~\ref{alg:alg_server_heterog} (\algname{Malenia SGD}) converges after at most $\bar{t}_{\ceil{\frac{24 L \Delta}{\varepsilon}}}$ seconds, where 
  \begin{align}
    \label{eq:upper_bound}
    \textstyle \bar{t}_k \eqdef \min\left\{t \geq 0 \, : \, \left(\frac{1}{n} \sum_{i=1}^n \flr{V_i(t) - V_i(\bar{t}_{k-1})}^{-1}\right)^{-1} \geq \max\left\{\frac{2 \sigma^2}{n \varepsilon}, 1\right\}\right\} \quad (\bar{t}_0 \equiv 0)
  \end{align}
  for all $k \geq 1.$
\end{restatable}

% \subsection{Discussion}

Up to constant factors, Theorem~\ref{theorem:random_lower_bound_heter_random} and Theorem~\ref{cor:max_time_params_heter} provide the optimal time complexity in the heterogeneous setting. The result is implicit, which is not a problem in practice since \algname{Malenia SGD} does not require $\{V_i\}$ to reach the optimality. Let us consider examples where we can get an explicit formula.

\begin{restatable}{example}{EXAMPLEHETERFIXED} [Fixed Computation Model in the Heterogeneous Setting]
  \label{eq:simple_heter}
  Assume that $v_i(t) = v_i$ with $v_i > 0$ for all $i \in [n].$ Then
  \begin{align}
    \label{eq:opt_heter_fixed}
    \textstyle \bar{t}_{\ceil{\frac{24 L \Delta}{\varepsilon}}} = \Theta\left(\max\limits_{i \in [n]} \frac{1}{v_i} + \left(\frac{1}{n} \sum_{i=1}^n \frac{1}{v_i}\right)\frac{\sigma^2}{n \varepsilon}\right).
  \end{align}
\end{restatable}

{
\begin{restatable}{example}{EXAMPLETRENDHETER} [Nonlinear Trend in the Heterogeneous Setting]
  \label{eq:example_share_heter}
  Assume that $v_i(t) = v_i \times g(t)$ with $v_i > 0$ for all $i \in [n]$ and a continuous almost everywhere positive function $g(t) \,:\, \R_{+}^{\infty} \to \R_{+}.$ Then
  \begin{align}
    \label{eq:bwvFomtFlwGBlgeblrheter}
    \textstyle \bar{t}_{\ceil{\frac{24 L \Delta}{\varepsilon}}} = G^{-1} \left(c_1 \cdot \left[\max\limits_{i \in [n]} \frac{1}{v_i} + \left(\frac{1}{n} \sum_{i=1}^n \frac{1}{v_i}\right)\frac{\sigma^2}{n \varepsilon}\right]\right),
  \end{align}
  where $G(t) \eqdef \int_{0}^{t} g(\tau) d \tau,$ and $c_1 \in [1/4, 4]$ (can depend on other parameters but is bounded).
\end{restatable}
}

Example~\ref{eq:simple_heter} shows that our result recovers the optimal complexity derived in \citep{tyurin2023optimal}. However, our time complexity works with virtually any computation model. 

\section{Conclusion}

To the best of our knowledge, this is the first work that provides optimal time complexities under virtually arbitrary computation behavior of workers in the distributed setting. We believe that our lower bounds, Theorems~\ref{theorem:random_lower_bound} and \ref{theorem:random_lower_bound_heter_random}, and upper bounds, Theorems~\ref{cor:max_time_params} and \ref{cor:max_time_params_heter}, close an important problem in parallel optimization. Our approach and techniques have the potential to serve as a foundation for solving other mathematical questions from parallel and asynchronous optimization in the future. {One interesting question is determining the optimal time complexities when the universal computation model is correlated with the randomness from stochastic gradients.}


