\section{Proof of Theorem~\ref{theorem:random_lower_bound}}
\label{sec:homog_proof}

In our lower bound proofs, we employ the following well-known function.
% This section considers the standard ``worst case'' function that helps to provide lower bounds in the nonconvex world. 
Let us define
\begin{align*}
    \textnormal{prog}(x) \eqdef \max \{i \geq 0\,|\,x_i \neq 0\} \quad (x_0 \equiv 1).
\end{align*}

For any $T \in \N,$ \citet{carmon2020lower,arjevani2022lower} define a function $F_T \,:\, \R^T \to \R$ such that
\begin{align}
    \label{eq:worst_case}
    F_T(x) = -\Psi(1) \Phi(x_1) + \sum_{i=2}^T \left[\Psi(-x_{i-1})\Phi(-x_i) - \Psi(x_{i-1})\Phi(x_i)\right],
\end{align}
where $x_i$ is the $i$\textsuperscript{th} coordinate of a vector $x \in \R^d$ and
\begin{align*}
    \Psi(x) = \begin{cases}
        0, & x \leq 1/2, \\
        \exp\left(1 - \frac{1}{(2x - 1)^2}\right), & x \geq 1/2,
    \end{cases}
    \quad\textnormal{and}\quad
    \Phi(x) = \sqrt{e} \int_{-\infty}^{x}e^{-\frac{1}{2}t^2}dt.
\end{align*}

% We will only rely on the following facts. 
In the proofs, we will only use the results from the following lemma.

\begin{lemma}[\cite{carmon2020lower, arjevani2022lower}]
    \label{lemma:worst_function}
    The function $F_T$ satisfies:
    \begin{enumerate}
        \item $F_T(0) - \inf_{x \in \R^T} F_T(x) \leq \Delta^0 T,$ where $\Delta^0 = 12.$
        \item The function $F_T$ is $l_1$--smooth, where $l_1 = 152.$
        \item For all $x \in \R^T,$ $\norm{\nabla F_T(x)}_{\infty} \leq \gamma_{\infty},$ where $\gamma_{\infty} = 23.$
        \item For all $x \in \R^T,$ $\textnormal{prog}(\nabla F_T(x)) \leq \textnormal{prog}(x) + 1.$
        \item For all $x \in \R^T,$ if $\textnormal{prog}(x) < T,$ then $\norm{\nabla F_T(x)} > 1.$
    \end{enumerate}
\end{lemma}

We are ready to prove our first main result.

