  First, we show that $f$ satisfies Assumptions~\ref{ass:lipschitz_constant}, \ref{ass:lower_bound} and $f(0) - f^* \leq \Delta.$ Let us show that the function $f$ is $L$-smooth. Indeed, we have
    \begin{align*}
        \norm{\nabla f(x) - \nabla f(y)}^2 &= \frac{1}{n^2}\norm{\sum_{i=1}^S \left(\nabla h_i(x) - \nabla h_i(y)\right)}^2 = \frac{1}{n^2}\sum_{i=1}^S \norm{\nabla h_i(x) - \nabla h_i(y)}^2\\
        &= \frac{1}{n^2}\sum_{i=1}^S \norm{\frac{n L \lambda}{l_1} \nabla F_{T}\left(\frac{x_i}{\lambda}\right) - \frac{n L \lambda}{l_1} \nabla F_{T}\left(\frac{y_i}{\lambda}\right)}_i^2,
    \end{align*}
    where $\norm{\cdot}_j$ is the Euclidean norm w.r.t. $j$\textsuperscript{th} block. Then,
    \begin{align*}
      \norm{\nabla f(x) - \nabla f(y)}^2 
      &= \frac{L^2 \lambda^2}{l_1^2} \sum_{i=1}^S \norm{\nabla F_{T}\left(\frac{x_i}{\lambda}\right) - \nabla F_{T}\left(\frac{y_i}{\lambda}\right)}_i^2 \leq L^2 \sum_{i=1}^S \norm{x_i - y_i}_i^2 = L^2 \norm{x - y}^2,
  \end{align*}
  where the last inequality due to Lemma~\ref{lemma:worst_function}.
    Let us take 
    \begin{align}
      \label{eq:luOePAy}
      T = \left\lfloor \frac{\Delta l_1}{L \lambda^2 S \Delta^0} \right\rfloor
    \end{align}
    then
    \begin{align*}
        f(0) - \inf_{x \in \R^{S \times T}} f(x) = \frac{1}{n} \sum_{i=1}^S \frac{n L \lambda^2}{l_1} (F_{T}\left(0\right) - \inf_{x \in \R^{T}} F_{T}(x)) \leq \frac{L \lambda^2 S \Delta^0 T}{l_1} \leq \Delta,
    \end{align*}
    where the first inequality due to Lemma~\ref{lemma:worst_function}.
    % We showed that the function $f \in \cF_{\Delta, L}.$

    (\textbf{Step 2}: Construction of local functions $f_i$) \\
    Each function $h_i(x)$ depends only on $T$ coordinates of the $i$\textsuperscript{th} block. We split these $T$ coordinates into $\bar{T} + 1$ groups with $\bar{T} \eqdef \flr{\nicefrac{T}{K}},$ where we choose $K$ later.
    % Let us fix $s_{i,j} \in \N_{0}$ for all $i \in [\bar{T}], j \in [n]$ and define
    For all $w \in [\bar{T} + 1],$ let us take any
    \begin{align}
      \label{eq:LGJeTrDgLlg}
      s_{w,0} \equiv 1 \leq s_{w,1} \leq \dots \leq s_{w,n - 1} \leq s_{w,n} \equiv S + 1.
    \end{align}
    It is convenient to define the length of each segment: $a_{w, i} \eqdef s_{w, i} - s_{w, (i - 1)}$ for all $w \in [\bar{T} + 1]$ and $i \in [n].$ Also, we take any times 
    \begin{align}
      \label{eq:LGJeTrDgLlgg}
      \bar{t}_0 \equiv 0 \leq \bar{t}_1 \leq \dots \leq \bar{t}_{\bar{T}} \leq \bar{t}_{\bar{T} + 1} \equiv \infty
    \end{align}
    associated with the coordinates' groups. We construct functions in the following way. For all $i \in [n],$ we define
    \begin{align*}
      &\widehat{f}_{i}(x) \eqdef \sum_{j=s_{1,(i-1)}}^{s_{1,i} - 1} \left(- \Psi(1)\Phi(x_{j,1}) + \dots + \Psi(-x_{j,K-1})\Phi(-x_{j,K}) - \Psi(x_{j,K-1})\Phi(x_{j,K})\right) \\
      &\quad+ \sum_{j=s_{2,(i-1)}}^{s_{2,i} - 1} \left(\Psi(-x_{j,K})\Phi(-x_{j,K+1}) - \Psi(x_{j,K})\Phi(x_{j,K+1}) + \dots \right.\\
      &\qquad\qquad\qquad\quad+\left. \Psi(-x_{j,2K - 1})\Phi(-x_{j,2 K}) - \Psi(x_{j,2 K-1})\Phi(x_{j,2 K})\right) \\
      &\quad+ \dots \\
      &\quad+ \sum_{j=s_{\bar{T},(i-1)}}^{s_{\bar{T},i} - 1} \left(\Psi(-x_{j,(\bar{T} - 1)K})\Phi(-x_{j,(\bar{T} - 1) K+1}) - \Psi(x_{j,(\bar{T} - 1)K})\Phi(x_{j,(\bar{T} - 1)K+1}) + \dots \right.\\
      &\qquad\qquad\qquad\quad+ \left.\Psi(-x_{j,\bar{T} K - 1})\Phi(-x_{j,\bar{T} K}) - \Psi(x_{j,\bar{T} K-1})\Phi(x_{j,\bar{T} K})\right) \\
      &\quad+ \sum_{j=s_{\bar{T} + 1,(i-1)}}^{s_{\bar{T} + 1,i} - 1} \left(\Psi(-x_{j,\bar{T} K})\Phi(-x_{j,\bar{T} K + 1}) - \Psi(x_{j,\bar{T} K})\Phi(x_{j,\bar{T} K + 1}) + \dots\right. \\
      &\qquad\qquad\qquad\quad+ \left.\Psi(-x_{j,T - 1})\Phi(-x_{j,T}) - \Psi(x_{j,T - 1})\Phi(x_{j,T})\right)
    \end{align*} 
    and 
    \begin{align*}
      f_{i}(x) \eqdef \frac{n L \lambda^2}{l_1} \widehat{f}_{i}\left(\frac{x}{\lambda}\right),
    \end{align*}
    where $x_{j,i}$ is the $i$\textsuperscript{th} coordinate of $x_j \in \R^{T}.$ 

    Let us explain the idea. For all $j \in [S],$ we take the function $h_j$ from \eqref{eq:func_g}, which consists of $T$ parts with the structure $\Psi(-x_{j,\cdot})\Phi(-x_{j,\cdot}) - \Psi(x_{j,\cdot})\Phi(x_{j,\cdot}),$ and distribute these parts between the workers according to the predefined segments $\{s_{w, i}\}.$ The first $K$ parts of the function $h_j$ will be stored in worker $i_1$ such that $s_{1, (i_1-1)} \leq j < s_{1, i_1},$ the second $K$ parts will be stored in worker $i_2$ such that $s_{2, (i_2-1)} \leq j < s_{2, i_2},$ and so on. One can easily show that $\sum_{j=1}^S h_j = \sum_{i=1}^n f_i.$ \\
    % We will take choose values for time time intervals $\bar{t}_0 \equiv 0 \leq \bar{t}_1 \leq \dots \leq \bar{t}_{\bar{T}}$ in such a way that \\
    (\textbf{Step 3}: Time-dependent stochastic oracles) \\
    We now construct a stochastic oracle. Let us take 
    \begin{align}
      \label{eq:uOIGCRiWeKzxBT}
      p_{w,i} \eqdef \min\left\{\frac{a_{w,i} n^2 L^2 \lambda^2 \gamma_{\infty}^2}{\sigma^2 l_1^2}, 1\right\}
    \end{align}
    for all $w \in [\bar{T} + 1], i \in [n].$
    The stochastic mapping takes a point $x,$ a random variable $\xi,$ a time $t,$ and returns
    \begin{equation}
    \begin{aligned}
      &[g_i(x; \xi, t)]_{j,m} \eqdef [\nabla f_{i}(x)]_{j,m} \times \\
      &\times \left(1 + \mathbbm{1}\left[m > \textnormal{prog}(x_j) \wedge \flr{\frac{m - 1}{K}} + 1  = w(t)\right]\left(\frac{\xi_{j,m}}{p_{w(t),i}} - 1\right)\right) \quad \forall x \in \R^{S \times T},
      \label{eq:JizJACFEaGQaVyyLArn}
    \end{aligned}
    \end{equation}
    where $[x]_{j,m}$ is the $m$\textsuperscript{th} coordinate of the $j$\textsuperscript{th} block of $x \in \R^{S \times T},$ $\{\xi_{j,m}\}_{j,m}$ are i.i.d. from $\textnormal{Bernoulli}(p_{w(t),i}),$ and $w(t) \in [\bar{T}]$ is the index such that $\bar{t}_{(w(t) - 1)} \leq t < \bar{t}_{w(t)}.$ 

    The idea is almost the same as in \citep{arjevani2022lower}: we also zero out the last potentially non-zero coordinate with the probability $p_{w(t),i}.$ However, we only zero out a coordinate if it belongs to the parts from the set $\{(K - 1)w(t) + 1, \dots, K w(t)\},$ where $w(t)$ is associated with the current time interval $[\bar{t}_{(w(t) - 1)}, \bar{t}_{w(t)})$ where the current time $t$ belongs to.

    Then, $g_i(x; \xi, t)$ is unbiased because $\ExpSub{\xi}{\left(\frac{\xi_{j,m}}{p_{w(t),i}} - 1\right)} = 0$ and 
    \begin{align*}
      \ExpSub{\xi}{\norm{g_i(x; \xi, t ) - \nabla f_i(x)}^2} 
      &\leq \sum_{j=s_{w(t),(i-1)}}^{s_{w(t),i} - 1} \frac{n^2 L^2 \lambda^2 \norm{\nabla F_{T}\left(\frac{x_j}{\lambda}\right)}_{\infty}^2(1 - p_{w(t),i})}{l_1^2 p_{w(t),i}}
    \end{align*}
    because, due the condition $\flr{\frac{m - 1}{K}} + 1  = w(t),$ we only consider the blocks from the sum $\sum_{j=s_{w(t),(i-1)}}^{s_{w(t),i} - 1}.$ 
    Using Lemma~\ref{lemma:worst_function}, we have $\norm{\nabla F_{T}\left(x\right)}_{\infty}^2 \leq \gamma_{\infty}^2$ for all $x \in \R^T$ and 
    \begin{align*}
      \ExpSub{\xi}{\norm{g_i(x; \xi, t ) - \nabla f_i(x)}^2} 
      &\leq \frac{a_{w(t),i} n^2 L^2 \lambda^2 \gamma_{\infty}^2 (1 - p_{w(t),i})}{l_1^2 p_{w(t),i}} \leq \sigma^2,
    \end{align*}
    where the last inequality follows from the choice of $p_{w,i}$ in \eqref{eq:uOIGCRiWeKzxBT}.

    (\textbf{Step 4}: Analysis of Protocol)

    Using the definition of $f,$ we get
    \begin{align}
        \norm{\nabla f(x)}^2 &= \frac{1}{n^2} \sum_{i=1}^S \norm{\nabla h_i(x)}^2 = \sum_{i=1}^S \frac{L^2 \lambda^2}{l_1^2}\norm{\nabla F_{T} \left(\frac{x_i}{\lambda}\right)}^2 \nonumber \\ 
        &> \frac{L^2 \lambda^2}{l_1^2} \sum_{i=1}^S \mathbbm{1}[\textnormal{prog} (x_i) < T]
    \end{align}
    for all $x = [x_1, \dots, x_n] \in \R^{T}.$ In the last inequality, we use Lemma~\ref{lemma:worst_function}. Let us take 
    \begin{align}
      \label{eq:JpjVFT}
      \lambda = \sqrt{\frac{4 \varepsilon l_1^2}{L^2 S}}.
    \end{align}
    to ensure that 
    \begin{align}
      \label{eq:BXRkHgCjoYtBSYF}
      \inf_{k \in S_t} \norm{\nabla f(x^k)}^2 > \inf_{k \in S_t} \frac{4 \varepsilon}{S} \sum_{i=1}^S \mathbbm{1}[\textnormal{prog} (x^k_i) < T] \geq \frac{4 \varepsilon}{S} \sum_{i=1}^S \inf_{k \in S_t} \mathbbm{1}[\textnormal{prog} (x^k_i) < T],
    \end{align}
    where $x^k$ are points defined in Protocol~\ref{alg:time_multiple_oracle_protocol}.
    Using Markov's inequality, we get
    \begin{equation}
    \begin{aligned}
      &\Prob{\frac{4 \varepsilon}{S} \sum_{i=1}^S \inf_{k \in S_t} \mathbbm{1}[\textnormal{prog} (x_i^k) < T] \leq 2 \varepsilon} \\
      &=\Prob{\frac{1}{S} \sum_{i=1}^S \inf_{k \in S_t} \mathbbm{1}[\textnormal{prog} (x_i^k) < T] \leq \frac{1}{2}} \\
      &= \Prob{\frac{1}{S} \sum_{i=1}^S \sup_{k \in S_t} \mathbbm{1}[\textnormal{prog} (x_i^k) \geq T] \geq \frac{1}{2}} \\\
      &\leq 2 \Exp{\frac{1}{S} \sum_{i=1}^S \sup_{k \in S_t} \mathbbm{1}[\textnormal{prog} (x_i^k) \geq T]} = \frac{2}{S} \sum_{i=1}^S \Exp{\sup_{k \in S_t} \mathbbm{1}[\textnormal{prog} (x_i^k) \geq T]}.
      \label{eq:tmszmJWkf}
    \end{aligned}
    \end{equation}

    (\textbf{Step 5}: Bound on the expectations)

    In this step of the proof, we fix $j \in [S],$ and consider the function $h_j$ from \eqref{eq:func_g}.

    Recall that worker $i$ can calculate $\flr{V_{i}(t)}$ stochastic gradients by a time $t.$ Therefore, it takes at least 
    \begin{align*}
      \min\left\{t \geq 0 \, : \, \flr{V_i(t)} \geq \eta\right\} \geq V_i^{-1}(\eta)
    \end{align*}
    seconds to calculate $\eta \in \N$ stochastic gradients, where we use the definition \eqref{eq:inv}.

    By the construction of the functions $\{f_i\},$ the first $K$ parts of $h_j$ belong to worker $i_{1,j}$ such that $s_{1,i_{1,j}-1} \leq j < s_{1,i_{1,j}}.$ While the algorithm $A$ is returning times $t^k$ such that $\bar{t}_0 \equiv 0 \leq t^k < \bar{t}_1,$ by the construction of the stochastic mapping \eqref{eq:JizJACFEaGQaVyyLArn}, whenever the algorithm calls oracle $O_{i_{1,j}},$ the oracle zeros out the last potentially non-zero coordinate with the probability $p_{1,i_{1,j}}.$ However, due to the condition $\flr{\frac{m - 1}{K}} + 1  = w(t),$ the stochastic mapping will zero out the first $K$ coordinates only if $t^k < \bar{t}_1.$ Thus, the time required to progress to the $K$\textsuperscript{th} coordinate in the block $x_j$ is at least
    \begin{align*}
      \hat{t}_{1,j} \eqdef \min\left\{\bar{t}_1, V^{-1}_{i_{1,j}}\left(\sum_{v=1}^{K} \eta_{1,i_{1,j},v}\right)\right\}
    \end{align*}
    seconds, where $\{\eta_{1,i_{1,j},v}\}$ are i.i.d. geometric random variables with the probability $p_{1,i_{1,j}}.$ Because either the algorithm returns $t^k \geq \bar{t}_1,$ or it keeps returning $t^k < \bar{t}_1,$ but then $A$ should calculate at least $\sum_{v=1}^{K} \eta_{1,i_{1,j},v}$ stochastic gradients since the stochastic mapping zeros out the last potentially non-zero coordinate, and $A$ should wait $K$ times for the ``lucky'' ($\xi = 1$) draws of Bernoulli random variables.

    Using the same reasoning, for all $w \in [\bar{T}],$ it will take at least 
    \begin{align}
      \label{eq:UllzpGb}
      \hat{t}_{w,j} \eqdef \min\left\{\bar{t}_w, V^{-1}_{i_{w,j}}\left(\sum_{v=1}^{K} \eta_{w,i_{w,j},v} + V_{i_{w,j}}(\hat{t}_{w - 1,j})\right)\right\} \qquad (\hat{t}_{0,j} \equiv 0)
    \end{align}
    seconds to progress to the $w \times K$\textsuperscript{th} coordinate in the block $x_j,$
    where $\{\eta_{w,i_{w,j},v}\}$ are i.i.d. geometric random variables with the probability $p_{w,i_{w,j}},$ and $i_{w,j}$ is the index of the worker such that $s_{w,i_{w,j}-1} \leq j < s_{w,i_{w,j}}.$
    Because either the algorithm returns $t^k \geq \bar{t}_w,$ or it keeps returning $t^k < \bar{t}_w,$ but then $A$ should first progress to the $(w - 1)\times K$\textsuperscript{th} coordinate, which takes at least $\hat{t}_{w - 1,j}$ seconds, and then should calculate at least $\sum_{v=1}^{K} \eta_{w,i_{w,j},v}$ stochastic gradients. This will take at least 
    \begin{align*}
      &\min\left\{t \geq 0 \, : \, \flr{V_{i_{w,j}}(t) - V_{i_{w,j}}(\hat{t}_{w - 1,j})} \geq \sum_{v=1}^{K} \eta_{w,i_{w,j},v}\right\} \\
      &\overset{(\textnormal{cont. of }V_{i_{w,j}})}{=}\min\left\{t \geq 0 \, : \, V_{i_{w,j}}(t) - V_{i_{w,j}}(\hat{t}_{w - 1,j}) = \sum_{v=1}^{K} \eta_{w,i_{w,j},v}\right\} \\
      &\overset{\eqref{eq:inv}}{=}V^{-1}_{i_{w,j}}\left(\sum_{v=1}^{K} \eta_{w,i_{w,j},v} + V_{i_{w,j}}(\hat{t}_{w - 1,j})\right)
    \end{align*}
    seconds. 
    % Therefore, it will take 

    Using Lemma~\ref{lemma:many_geom}, with a probability at least $1 - \bar{T} e^{- K / 2},$ we have
    % \begin{align*}
    %   \sum_{v=1}^{K} \eta_{1,i_{1,j},v} \geq c_1 \times \frac{K}{p_{1,i_{1,j}}}, \sum_{v=1}^{K} \eta_{2,i_{2,j},v} \geq c_1 \times \frac{K}{p_{2,i_{2,j}}}, \dots
    % \end{align*}
    \begin{align*}
      \sum_{v=1}^{K} \eta_{w,i_{w,j},v} \geq \frac{K}{8 p_{w,i_{w,j}}}
    \end{align*}
    for all $w \in [\bar{T}].$
    Using these inequalities and \eqref{eq:UllzpGb}, we get
    \begin{align}
      \label{eq:YPBcANcxqHC}
      \hat{t}_{w,j} \geq \min\left\{\bar{t}_w, V^{-1}_{i_{w,j}}\left(\frac{K}{8 p_{w,i_{w,j}}} + V_{i_{w,j}}(\hat{t}_{w-1,j})\right)\right\},
    \end{align}
    for all $w \in [\bar{T}].$
    % \begin{align*}
    %   \hat{t}_1 \geq \min\left\{\bar{t}_1, F^{-1}_{i_1}\left(\frac{K}{p_{1,i_1}}\right)\right\}.
    % \end{align*}
    % In Lemma~\ref{???}, we choose $p_{1,i_1}$ such that $F^{-1}_{i_1}\left(\frac{K}{p_{1,i_1}}\right) \geq \bar{t}_1.$ 

    Note that $\{\bar{t}_w\}_{w=1}^{\bar{T}},$$\{s_{w,i}\}_{w \in [\bar{T} + 1], i \in [n]},$ and $S$ are free parameters with the conditions \eqref{eq:LGJeTrDgLlg} and \eqref{eq:LGJeTrDgLlgg}. Due to \eqref{eq:uOIGCRiWeKzxBT} and \eqref{eq:JpjVFT}, we have
    \begin{align*}
      p_{w,i} = \min\left\{\frac{4 \varepsilon \gamma_{\infty}^2 a_{w,i} n^2}{\sigma^2 S}, 1\right\}.
    \end{align*}
    Therefore, we can use Lemma~\ref{lemma:params}: we can find $\{\bar{t}_w\}_{w=1}^{\bar{T}},$$\{s_{w,i}\}_{w \in [\bar{T} + 1], i \in [n]},$ and $S$ such that $V^{-1}_{i}\left(\frac{K}{8 p_{1,i}}\right) \geq \bar{t}_1$ for all $i \in [n].$ 
    With a probability at least $1 - \bar{T} e^{- K / 2},$ with the chosen parameters, we have 
    \begin{align*}
      \hat{t}_{1,j} \geq \min\left\{\bar{t}_1, V^{-1}_{i_{1,j}}\left(\frac{K}{8 p_{1,i_{1,j}}}\right)\right\} \geq \min\left\{\bar{t}_1, \bar{t}_1\right\} = \bar{t}_1.
    \end{align*}

    Using a proof by induction, with a probability at least $1 - \bar{T} e^{- K / 2},$ let us prove that $\hat{t}_{w,j} \geq \bar{t}_w$ for all $w \in [\bar{T}]$ with the parameters from Lemma~\ref{lemma:params}. The base case has been proved. Assume that $$\hat{t}_{w - 1,j} \geq \bar{t}_{w - 1},$$ then, using \eqref{eq:YPBcANcxqHC}, we get
    \begin{align*}
      \hat{t}_{w,j} \geq \min\left\{\bar{t}_w, V^{-1}_{i_{w,j}}\left(\frac{K}{8 p_{w,i_{w,j}}} + V_{i_{w,j}}(\hat{t}_{w-1,j})\right)\right\} \geq \min\left\{\bar{t}_w, V^{-1}_{i_{w,j}}\left(\frac{K}{8 p_{w,i_{w,j}}} + V_{i_{w,j}}(\bar{t}_{w-1})\right)\right\}.
    \end{align*}
    In Lemma~\ref{lemma:params}, we show that $V^{-1}_{i}\left(\frac{K}{8 p_{w,i}} + V_{i}(\bar{t}_{w-1})\right) \geq \bar{t}_w$ for all $i \in [n].$ Thus
    \begin{align*}
      \hat{t}_{w,j} \geq \min\left\{\bar{t}_w, \bar{t}_w\right\} = \bar{t}_w.
    \end{align*}

    (\textbf{Step 6}: Choose a parameter $K$) \\
    In the previous step, we prove that, with a probability at least $1 - \bar{T} e^{- K / 2},$ the algorithm requires at least $\bar{t}_{\bar{T}}$ seconds to progress to the $K \times \bar{T}$\textsuperscript{th} coordinate ($K \times \bar{T} \leq T$), where $\bar{t}_{\bar{T}}$ is defined in in the proof of Lemma~\ref{lemma:params}.

    Let us take 
    \begin{align*}
      K = \flr{2 \log 4 T},
    \end{align*}
    then, with a probability at least $3 / 4,$ the algorithm will require at least $\bar{t}_{\bar{T}}$ seconds to get a non-zero last coordinate in the block $x_j.$ Thus
    \begin{align*}
      \Exp{\sup_{k \in S_t} \mathbbm{1}[\textnormal{prog} (x_j^k) \geq T]} \leq \frac{1}{4}
    \end{align*}
    for all $j \in [n]$ and for all $t \leq \frac{1}{2} \bar{t}_{\bar{T}}.$ We substitute these inequalities to \eqref{eq:tmszmJWkf} and \eqref{eq:BXRkHgCjoYtBSYF}, and get
    \begin{align*}
      \Prob{\frac{4 \varepsilon}{S} \sum_{i=1}^S \inf_{k \in S_t} \mathbbm{1}[\textnormal{prog} (x_i^k) < T] \leq 2 \varepsilon} \leq \frac{1}{2}
    \end{align*}
    and 
    \begin{align*}
      \Exp{\inf_{k \in S_t} \norm{\nabla f(x^k)}^2} > \Exp{\frac{4 \varepsilon}{S} \sum_{i=1}^S \inf_{k \in S_t} \mathbbm{1}[\textnormal{prog} (x^k_i) < T]} > 2 \varepsilon \Prob{\frac{4 \varepsilon}{S} \sum_{i=1}^S \inf_{k \in S_t} \mathbbm{1}[\textnormal{prog} (x_i^k) < T] > 2 \varepsilon} \geq \varepsilon
    \end{align*}
    for all 
    \begin{align*}
      t \leq \frac{1}{2} \widetilde{t}_{\bar{T}} \overset{\eqref{eq:TToceJIF}}{\leq} \frac{1}{2} \bar{t}_{\bar{T}},
    \end{align*}
    where \begin{align*}
      \bar{T} = \flr{\frac{T}{\flr{2 \log 4 T}}} \overset{\eqref{eq:luOePAy}, \eqref{eq:JpjVFT}}{\geq} \flr{\frac{c_1 \times \frac{L \Delta}{\varepsilon}}{\log \frac{L \Delta}{\varepsilon}}}
    \end{align*}
    for some universal constant $c_1,$ where we use the assumption $\varepsilon < c' L \Delta$ of the theorem. Finally, since $\widetilde{t}_{w} \geq \underline{t}_{w}$ for all $w \in [\bar{T}]$ with the chosen $K,$ where the later sequence is defined in \eqref{eq:iTLiJe},
    % and equals to 
    % \begin{align*}
    %   \underline{t}_{w} &= \min\left\{t \geq 0 \,:\,\left(\frac{1}{n}\sum_{i=1}^n \frac{1}{\flr{c_3 \times \frac{V_{i}\left(t\right) - V_{i} (\underline{t}_{w - 1})}{\log \left(\frac{L \Delta}{\varepsilon}\right)}}}\right)^{-1} \geq \max\left\{c_2 \times \frac{\sigma^2}{n \varepsilon}, 1\right\} \right\} \\
    %   &= \min\left\{t \geq 0 \,:\,\frac{1}{n}\sum_{i=1}^n \frac{1}{\flr{c_3 \times \frac{V_{i}\left(t\right) - V_{i} (\underline{t}_{w - 1})}{\log \left(\frac{L \Delta}{\varepsilon}\right)}}} \leq \min\left\{\frac{n \varepsilon}{c_2 \sigma^2}, 1\right\} \right\}
    % \end{align*}
    % for all $w \in [\bar{T}],$
    we can take
    \begin{align*}
      t = \frac{1}{2} \underline{t}_{\flr{\frac{c_1 \times \frac{L \Delta}{\varepsilon}}{\log \frac{L \Delta}{\varepsilon}}}}.
    \end{align*}
    \end{proof}

\section{Proof of Theorem~\ref{theorem:random_lower_bound_heter_random}}

\RANDOMLOWERBOUNDFULLHETERRANDOM*

\begin{proof}
  We base our proof on the function $F_T(x)$ from Section~\ref{sec:homog_proof}. Let us fix any algorithm $A \in \mathcal{A}_{\textnormal{zr}}.$ 
  First, we define $S \in \N$ functions such that, for all $j \in [S],$ we have $h_j(x)\,:\,\R^{S \times T} \to \R$ and
  \begin{align}
    \label{eq:func_g_random}
    h_j(x) = \frac{n L \lambda^2}{l_1} F_{T}\left(\frac{x_j}{\lambda}\right),
  \end{align}
  where $T,$ $S,$ and $\lambda$ are defined later. We assume that $x = [x_1, \dots, x_S] \in \R^{S \times T}.$ We define $x_j \in \R^{T}$ as the $j$\textsuperscript{th} block of a vector $x = [x_1, \dots, x_S] \in \R^{S \times T}.$ The function $h_j$ depends only on a subset of variables $x_j$ from $x.$ We construct a function $f\,:\,\R^{S \times T} \to \R$ such that
  \begin{align}
    \label{eq:GsQfHULIoFKD_random}
    f(x) = \frac{1}{n} \sum_{i=1}^S h_i(x).
  \end{align}
  While the final structure of the local stochastic functions $f_i$ is not yet defined, during the proof, we will ensure that \eqref{eq:GsQfHULIoFKD_random} holds.

  (\textbf{Step 1}: $f \in \cF_{\Delta, L}$) \\
  We have to show that $f$ satisfies Assumptions~\ref{ass:lipschitz_constant}, \ref{ass:lower_bound} and $f(0) - f^* \leq \Delta.$ This step is exactly the same as in the proof of Theorem~\ref{theorem:random_lower_bound_heter}. It is sufficient to take 
  \begin{align}
    \label{eq:luOePAy_random}
    T = \left\lfloor \frac{\Delta l_1}{L \lambda^2 S \Delta^0} \right\rfloor.
  \end{align}

  (\textbf{Step 2}: Construction of local functions $f_i$ and stochastic mappings) \\
  Unlike the proof of Theorem~\ref{theorem:random_lower_bound_heter} where the functions are predetermined, in this construction the functions $\{f_i\}$ depend on sequences of random variables and are constructed algorithmically in the following way.

  For all $w \in [T + 1],$ let us take any
  \begin{align}
    \label{eq:BZjAsfDsrOOEsFIQk}
    s_{w,0} \equiv 1 \leq s_{w,1} \leq \dots \leq s_{w,n - 1} \leq s_{w,n} \equiv S + 1,
  \end{align}
  and define $a_{w, i} \eqdef s_{w, i} - s_{w, (i - 1)}.$
  We also take any $p_{w,i} > 0$ for all $w \in [T], i \in [n],$ and any times 
  \begin{align}
    \label{eq:BZjAsfDsrOOEsFIQkk}
    \bar{t}_0 \equiv 0 \leq \bar{t}_1 \leq \dots \leq \bar{t}_{T} \leq \bar{t}_{T + 1} \equiv \infty
  \end{align}
  associated with $\{s_{w,\cdot}\}_{w \in [T+1]}$ and $\{p_{w,\cdot}\}_{w \in [T]}$. We construct the functions $\{f_i\}$ using the algorithm below.
  \begin{algorithm}[H]
    \caption{``Resisting allocation'' of the functions $\{h_j\}$}
    \label{alg:resisting}
    \begin{algorithmic}[1]
    \STATE $f_{i}(x) \leftarrow 0$ for all $i \in [n]$
    \FOR{$j = 1, \dots, S$}
    \STATE Current time window $w = 1$
    \FOR{$m = 1, \dots, T$}
    \STATE Find $i_{w,j}$ such that $s_{w,i_{w,j}-1} \leq j < s_{w,i_{w,j}}$
    \STATE Set $b_{j,m} \leftarrow (w, i_{w,j})$
    \STATE Update $f_{i_{w,j}}(x) \leftarrow f_{i_{w,j}}(x) + \frac{n L \lambda^2}{l_1} \left(\Psi\left(-\frac{x_{j,m-1}}{\lambda}\right)\Phi\left(-\frac{x_{j,m}}{\lambda}\right) - \Psi\left(\frac{x_{j,m-1}}{\lambda}\right)\Phi\left(\frac{x_{j,m}}{\lambda}\right)\right)$ \\
    ($x_{j,0} \equiv 0$ for all $j \in [S]$)
    % \STATE Draw an infinite sequence $\{\xi_{j,m,s}\}_{s=1}^{\infty}$ from $\textnormal{Bernoulli}(p_{w,i_{w,j}})$ 
    \STATE Draw an infinite i.i.d. sequence $\{\xi_{j,m,s}\}_{s=1}^{\infty}$ from $\textnormal{Bernoulli}(p_{w,i_{w,j}})$ \alglinelabel{line:sample}
    \STATE Find the first moment when $\xi_{j,m,s} = 1,$ i.e., $\eta_{j,m} = \inf\{s \geq 1 \,:\, \xi_{j,m,s} = 1\}$ \\
    \IF{$V^{-1}_{i_{w,j}}\left(\eta_{j,m} + V_{i_{w,j}}(\bar{t}_{w - 1})\right) \geq \bar{t}_{w}$} \alglinelabel{line:iforig}
    \STATE $w \leftarrow w + 1$
    \ENDIF
    \ENDFOR
    \ENDFOR
    \end{algorithmic}
  \end{algorithm}

  As in the proof of Theorem~\ref{theorem:random_lower_bound_heter}, the stochastic mapping takes a point $x,$ a random variable $\xi,$ a time $t,$ and returns
  % \begin{equation}
  % \begin{aligned}
  %   &[g_i(x; \xi, t)]_{j,m} \eqdef [\nabla f_{i}(x)]_{j,m} \times \\
  %   &\times \left(1 + \mathbbm{1}\left[m = \textnormal{prog}(x_j) + 1 \wedge b_{j,m} = (w(t), i) \right]\left(\frac{\xi}{p_{w(t),i}} - 1\right)\right) \quad \forall x \in \R^{S \times T},
  %   \label{eq:JizJACFEaGQaVyyLArn_random}
  % \end{aligned}
  % \end{equation}
  \begin{equation}
    \begin{aligned}
      [g_i(x; \bar{\xi}, t)]_{j,m} \eqdef 
      \begin{cases}
        [\nabla f_{i}(x)]_{j,m} \times \frac{\bar{\xi}_j}{p_{w(t),i}}, & m = \textnormal{prog}(x_j) + 1 \wedge b_{j,m} = (w(t), i), \\
        [\nabla f_{i}(x)]_{j,m}, & \textnormal{otherwise},
      \end{cases}
      \label{eq:JizJACFEaGQaVyyLArn_random}
    \end{aligned}
    \end{equation}
  where $[x]_{j,m}$ is the $m$\textsuperscript{th} coordinate of the $j$\textsuperscript{th} block of $x \in \R^{S \times T},$ 
  % $\{\xi_{j,m}\}$ are i.i.d. from $\textnormal{Bernoulli}(p_{w(t),i}),$
  $\bar{\xi} \equiv (\bar{\xi}_1, \dots, \bar{\xi}_{S}),$
  $\bar{\xi}_j$ is the ``next'' random variable from $\{\xi_{j, (\textnormal{prog}(x_j) + 1), s}\}_{s=1}^{\infty}$ (see Alg.~\ref{alg:resisting}),
  and $w(t) \in [T]$ is the index such that $\bar{t}_{(w(t) - 1)} \leq t < \bar{t}_{w(t)}.$ 

  Let us clarify what we mean by the ``next'' random variable. In \begin{NoHyper}Line~\ref{line:sample}\end{NoHyper} of Alg.~\ref{alg:resisting}, we draw an infinite i.i.d. sequence $\{\xi_{j,m,s}\}_{s=1}^{\infty}$ from $\textnormal{Bernoulli}(p_{w,i_{w,j}}).$ For the first time when the mapping $g_i$ has to take the ``next'' random variable from $\{\xi_{j, (\textnormal{prog}(x_j) + 1), s}\}_{s=1}^{\infty},$ it takes $\xi_{j, (\textnormal{prog}(x_j) + 1), 1}.$ For the second time, it takes $\xi_{j, (\textnormal{prog}(x_j) + 1), 2},$ and so forth.

  For all $i \in [n],$ the mapping $g_i$ in the oracle $O_i$ zeroes out the coordinate $m$ of the gradient $\nabla f_{i}(x)$ corresponding to $m = \textnormal{prog}(x_j) + 1$ (idea is the same as in \citep{arjevani2022lower}). However, we only zero out this coordinate if the corresponding part of the function $h_j$ is stored on worker $i$ at the time $t$ (condition $b_{j,m} = (w(t), i)$).
  % Every time when the oracle \eqref{eq:oracle_inside_random_heter} calls the mapping $g_i,$ the mapping/oracle takes 

  We now explain the idea. 
  For all $i \in [n],$ deterministically, we have 
  \begin{align*}
    f_{i}(x) = \frac{n L \lambda^2}{l_1} \sum_{j=s_{1,i-1} + 1}^{s_{1,i}} - \Psi(1) \Phi\left(\frac{x_{j,1}}{\lambda}\right) + \dots.
  \end{align*}
  where $x_{j,i}$ is the $i$\textsuperscript{th} coordinate of $x_j \in \R^{T}.$ Thus, the first part $-\Psi(1) \Phi(x_1)$ of the functions \eqref{eq:func_g_random} (see \eqref{eq:worst_case}) are allocated according to the values $\{s_{1,i}\}.$ 

  As always, we rely on the fact that the algorithm is zero-respecting, meaning that at the beginning, it starts with the point $x^0 = 0.$ While $x^k = 0,$ it does not matter where we allocate the other parts of the functions $h_j.$ The main idea is to decide the allocation based on the random variables $\{\xi_{j,m,s}\}_{s=1}^{\infty}$ from Alg.~\ref{alg:resisting}. By the construction of the functions $\{f_i\},$ the first part of $h_j$ belongs to worker $i_{1,j}$ such that $s_{1,i_{1,j}-1} \leq j < s_{1,i_{1,j}}.$ The oracle $O_{i_{1,j}}$ zeroes out the first coordinate of the $j$\textsuperscript{th} block of gradients with the probability $p_{1,i_{1,j}}$ (see \eqref{eq:JizJACFEaGQaVyyLArn_random}). 

  % Before the time $\hat{t}_{1,j},$ we could allocate the second block of the function $g_j$ to any worker. The time $\hat{t}_{1,j}$ is the earliest time when we should decide where to allocate the second block.

  In Alg.~\ref{alg:resisting}, we consider two cases: \\
  If $V^{-1}_{i_{1,j}}\left(\eta_{j,1}\right) < \bar{t}_1,$ then in the next iteration of Alg.~\ref{alg:resisting}, we allocate the second part of the function $h_j$ to the same worker $i_{1,j},$ i.e., 
  \begin{align*}
    f_{i_{1,j}}(x) \leftarrow f_{i_{1,j}}(x) + \frac{n L \lambda^2}{l_1} \left(\Psi\left(-\frac{x_{j,1}}{\lambda}\right)\Phi\left(-\frac{x_{j,2}}{\lambda}\right) - \Psi\left(\frac{x_{j,1}}{\lambda}\right)\Phi\left(\frac{x_{j,2}}{\lambda}\right)\right).
  \end{align*}
  Otherwise, if $V^{-1}_{i_{1,j}}\left(\eta_{j,1}\right) \geq \bar{t}_1,$ then we increment the parameter $w$ in Alg.~\ref{alg:resisting} and allocate the second part to  worker $i_{2,j}:$
  \begin{align*}
    f_{i_{2,j}}(x) \leftarrow f_{i_{2,j}}(x) + \frac{n L \lambda^2}{l_1} \left(\Psi\left(-\frac{x_{j,1}}{\lambda}\right)\Phi\left(-\frac{x_{j,2}}{\lambda}\right) - \Psi\left(\frac{x_{j,1}}{\lambda}\right)\Phi\left(\frac{x_{j,2}}{\lambda}\right)\right),
  \end{align*}
  where $i_{2,j}$ such that $s_{2,i_{,j}-1} \leq j < s_{2,i_{2,j}}.$

  The mapping $g_i$ is unbiased and $\sigma^2$--variance bounded. 
  If $m > \textnormal{prog}(x_j) + 1,$ then $[\nabla f_{i}(x)]_{j,m} = 0$ deterministically due to Lemma~\ref{lemma:worst_function}.
  If $m = \textnormal{prog}(x_j) + 1$ and $b_{j,m} = (w(t), i),$ then we have to show that
  \begin{align*}
    \ExpSub{\bar{\xi}}{[\nabla f_{i}(x)]_{j,m} \times \frac{\bar{\xi}_j}{p_{w(t),i}}} = [\nabla f_{i}(x)]_{j,m}
  \end{align*}
  for all $j \in [S], m \in [T].$ 
  % Notice that due the construction in Alg.~\ref{alg:resisting}, the gradient $\nabla f_{i}(x)$ can depend on $\xi_j$ from $\{\xi_{j, m, s}\}$ since they define the allocation of blocks starting from 
  Notice that due the construction in Alg.~\ref{alg:resisting}, the gradient $\nabla f_{i}(x)$ can depend on $\{\xi_{j,m,s}\}_{s=1}^{\infty}$ since the random variables affect the allocation of parts starting from 
  \begin{equation}
  \begin{aligned}
    \label{eq:EHtZvQJEAH}
    % &\Psi\left(-\frac{x_{j,0}}{\lambda}\right)\Phi\left(-\frac{x_{j,1}}{\lambda}\right) - \Psi\left(\frac{x_{j,0}}{\lambda}\right)\Phi\left(\frac{x_{j,1}}{\lambda}\right),
    % &\dots\\
    &\Psi\left(-\frac{x_{j,m}}{\lambda}\right)\Phi\left(-\frac{x_{j,m+1}}{\lambda}\right) - \Psi\left(\frac{x_{j,m}}{\lambda}\right)\Phi\left(\frac{x_{j,m+1}}{\lambda}\right), \\
    &\Psi\left(-\frac{x_{j,m+1}}{\lambda}\right)\Phi\left(-\frac{x_{j,m+2}}{\lambda}\right) - \Psi\left(\frac{x_{j,m+1}}{\lambda}\right)\Phi\left(\frac{x_{j,m+2}}{\lambda}\right), \\
    &\dots \\
    &\Psi\left(-\frac{x_{j,T-1}}{\lambda}\right)\Phi\left(-\frac{x_{j,T}}{\lambda}\right) - \Psi\left(\frac{x_{j,T-1}}{\lambda}\right)\Phi\left(\frac{x_{j,T}}{\lambda}\right).
  \end{aligned}
  \end{equation}
  However, i) the $j$\textsuperscript{th} block does no depend on $\xi_{j',m',s'}$ with $j' \neq j, m' \in [T], s' \geq 1$ ii) all the previous parts in the $j$\textsuperscript{th} block depend only on $\{\xi_{j, m', s}\}_{m' < m, s \geq 1},$ and iii) all the parts from \eqref{eq:EHtZvQJEAH} are zero because $m = \textnormal{prog}(x_j) + 1.$ Therefore
  \begin{align*}
    \ExpSub{\bar{\xi}}{[\nabla f_{i}(x)]_{j,m} \times \frac{\bar{\xi}_j}{p_{w(t),i}}} 
    &\overset{\textnormal{i)}}{=} \ExpSub{\bar{\xi}_j}{[\nabla f_{i}(x)]_{j,m} \times \frac{\bar{\xi}_j}{p_{w(t),i}}} \\
    &\overset{\textnormal{ii), iii)}}{=} [\nabla f_{i}(x)]_{j,m} \ExpSub{\bar{\xi}_j}{\frac{\bar{\xi}_j}{p_{w(t),i}}} = [\nabla f_{i}(x)]_{j,m}.
  \end{align*}
  For $m = \textnormal{prog}(x_j) + 1$ and $b_{j,m} \neq (w(t), i),$ we have
  \begin{align*}
    \ExpSub{\bar{\xi}}{[g_i(x; \bar{\xi}, t)]_{j,m}} = \ExpSub{\bar{\xi}}{[\nabla f_{i}(x)]_{j,m}} \overset{\textnormal{i)}}{=} \ExpSub{\bar{\xi}_j}{[\nabla f_{i}(x)]_{j,m}} \overset{\textnormal{ii), iii)}}{=} [\nabla f_{i}(x)]_{j,m}.
  \end{align*} 
  For $m < \textnormal{prog}(x_j) + 1,$ we have
  \begin{align*}
    \ExpSub{\bar{\xi}}{[g_i(x; \bar{\xi}, t)]_{j,m}} = \ExpSub{\bar{\xi}}{[\nabla f_{i}(x)]_{j,m}} \overset{\textnormal{i)}}{=} \ExpSub{\bar{\xi}_j}{[\nabla f_{i}(x)]_{j,m}} \overset{\textnormal{ii)}}{=} [\nabla f_{i}(x)]_{j,m}.
  \end{align*} 
  Using the same reasoning, we have
  \begin{align*}
    &\ExpSub{\bar{\xi}}{\norm{g_i(x; \bar{\xi}, t) - \nabla f_i(x)}^2} \\
    &=\ExpSub{\bar{\xi}}{\sum_{\substack{j,m \,:\, b_{j,m} = (w(t), i), \\ m = \textnormal{prog}(x_j) + 1}} \left([\nabla f_i(x)]_{j,m}\right)^2 \left(\frac{\bar{\xi}_j}{p_{w(t),i}} - 1\right)^2} \\
    &=\sum_{\substack{j,m \,:\, b_{j,m} = (w(t), i), \\ m = \textnormal{prog}(x_j) + 1}} \left([\nabla f_i(x)]_{j,m}\right)^2 \ExpSub{\bar{\xi}}{\left(\frac{\bar{\xi}_j}{p_{w(t),i}} - 1\right)^2} \\
    &=\sum_{\substack{j,m \,:\, b_{j,m} = (w(t), i), \\ m = \textnormal{prog}(x_j) + 1}} \left([\nabla f_i(x)]_{j,m}\right)^2 \frac{\left(1 - p_{w(t),i}\right)}{p_{w(t),i}} \\
    &=\sum_{\substack{j,m \,:\, b_{j,m} = (w(t), i), \\ m = \textnormal{prog}(x_j) + 1}} \left(\left[\nabla F_T\left(\frac{x_j}{\lambda}\right)\right]_{m}\right)^2 \frac{n^2 L^2 \lambda^2 \left(1 - p_{w(t),i}\right)}{l_1^2 p_{w(t),i}}.
    % &\leq \sum_{j=s_{w(t),(i-1)}}^{s_{w(t),i} - 1} \frac{n^2 L^2 \lambda^2 \norm{\nabla F_{T}\left(\frac{x_j}{\lambda}\right)}_{\infty}^2(1 - p_{w(t),i})}{l_1^2 p_{w(t),i}}
  \end{align*}
  Due to Lemma~\ref{lemma:worst_function}, we get $\norm{\nabla F_{T}\left(x\right)}_{\infty}^2 \leq \gamma_{\infty}^2$ for all $x \in \R^T$ and 
  \begin{align*}
    \ExpSub{\bar{\xi}}{\norm{g_i(x; \bar{\xi}, t) - \nabla f_i(x)}^2} 
    &\leq \sum_{\substack{j,m \,:\, b_{j,m} = (w(t), i), \\ m = \textnormal{prog}(x_j) + 1}} \frac{n^2 L^2 \lambda^2 \gamma_{\infty}^2 \left(1 - p_{w(t),i}\right)}{l_1^2 p_{w(t),i}} \\
    &= \frac{a_{w(t),i} n^2 L^2 \lambda^2 \gamma_{\infty}^2 \left(1 - p_{w(t),i}\right)}{l_1^2 p_{w(t),i}}
  \end{align*}
  because, due the condition $b_{j,m} = (w(t), i),$ we only consider the blocks from the set $\{s_{w(t),(i-1)}, \dots, s_{w(t),i} - 1\}$ (see Alg.~\ref{alg:resisting}), take one coordinate from each block, and recall that $a_{w(t),i} \eqdef s_{w(t),i} - s_{w(t),(i-1)}.$ Using the choice 
  % \eqref{eq:uOIGCRiWeKzxBT} of $p_{w,i}$ as in the proof of Theorem~\ref{theorem:random_lower_bound_heter}, 
  \begin{align}
    \label{eq:uOIGCRiWeKzxBT_random}
    p_{w,i} \eqdef \min\left\{\frac{a_{w,i} n^2 L^2 \lambda^2 \gamma_{\infty}^2}{\sigma^2 l_1^2}, 1\right\}
  \end{align}
  for all $w \in [T], i \in [n],$ we get
  \begin{align*}
    \ExpSub{\bar{\xi}}{\norm{g_i(x; \bar{\xi}, t) - \nabla f_i(x)}^2} \leq \sigma^2.
  \end{align*}

  (\textbf{Step 3}: Analysis of Protocol)

  Mirroring the proof of Theorem~\ref{theorem:random_lower_bound_heter}, using 
  \begin{align}
    \label{eq:JpjVFT_random}
    \lambda = \sqrt{\frac{4 \varepsilon l_1^2}{L^2 S}},
  \end{align}
  one can show
  \begin{align}
    \label{eq:BXRkHgCjoYtBSYF_random}
    \inf_{k \in S_t} \norm{\nabla f(x^k)}^2 > \frac{4 \varepsilon}{S} \sum_{i=1}^S \inf_{k \in S_t} \mathbbm{1}[\textnormal{prog} (x^k_i) < T],
  \end{align}
  where $x^k$ are points defined in Protocol~\ref{alg:time_multiple_oracle_protocol}, and 
  \begin{equation}
  \begin{aligned}
    \Prob{\frac{4 \varepsilon}{S} \sum_{i=1}^S \inf_{k \in S_t} \mathbbm{1}[\textnormal{prog} (x_i^k) < T] \leq 2 \varepsilon} \leq \frac{2}{S} \sum_{i=1}^S \Exp{\sup_{k \in S_t} \mathbbm{1}[\textnormal{prog} (x_i^k) \geq T]}.
    \label{eq:tmszmJWkf_random}
  \end{aligned}
  \end{equation}

  (\textbf{Step 4}: Bound on the expectations)

  The time required to progress (get a non-zero value) to the $1$\textsuperscript{th} coordinate in the block $x_j$ is at least
  \begin{align*}
    % \hat{t}_{1,j} \eqdef \min\left\{\bar{t}_1, V^{-1}_{i_{1,j}}\left(\eta_{1,i_{1,j},1}\right)\right\}
    \min\left\{\bar{t}_1, V^{-1}_{i_{1,j}}\left(\eta_{j,1}\right)\right\}
  \end{align*}
  seconds, where $V^{-1}_i$ is defined in \eqref{eq:inv} and $\eta_{j,1}$ is a geometric random variable with the probability $p_{1,i_{1,j}}.$  
  Because, due the condition $b_{j,1} \equiv (1,i_{1,j}) = (w(t), i)$, the mapping \eqref{eq:JizJACFEaGQaVyyLArn_random} zeroes out the first coordinate only if the algorithm returns $t^k < \bar{t}_1$ and $i_{1,j} = i.$ Therefore, either the algorithm returns $t^k \geq \bar{t}_1$ and \eqref{eq:JizJACFEaGQaVyyLArn_random} does not zero out the coordinate of gradients,
  or it keeps returning $t^k < \bar{t}_1,$ but then $A$ should calculate at least $\eta_{j,1}$ stochastic gradients in worker $i_{1,j}$ since the stochastic mapping zeros out the potentially non-zero coordinate in \eqref{eq:JizJACFEaGQaVyyLArn_random}.

  Recall that the ``resisting'' allocator (Alg.~\ref{alg:resisting}) tracks the random variable $\eta_{j,1}.$ \\
  \textbf{Opt. 1:} If $V^{-1}_{i_{1,j}}\left(\eta_{j,1}\right) < \bar{t}_1,$ then Alg.~\ref{alg:resisting} allocates the second part of the function $h_j$ to the same worker $i_{1,j},$ meaning 
  that the time required to progress (get a non-zero value) to the $2$\textsuperscript{th} coordinate in the block $x_j$ is at least
  \begin{align*}
    &\min\left\{\bar{t}_1, V^{-1}_{i_{1,j}}\left(\eta_{j,1} + \eta_{j,2}\right)\right\} \geq \min\left\{\bar{t}_1, V^{-1}_{i_{1,j}}\left(\eta_{j,2}\right)\right\}
  \end{align*}
  seconds, where $\eta_{j,2}$ is a geometric random variable with the probability $p_{1,i_{1,j}}.$ \\
  \textbf{Opt. 2:} If $V^{-1}_{i_{1,j}}\left(\eta_{j,1}\right) \geq \bar{t}_1,$ then we allocate the second part to worker $i_{2,j},$ where $i_{2,j}$ such that $s_{1,i_{2,j}-1} \leq j < s_{1,i_{2,j}},$ meaning that the time required to progress (get a non-zero value) to the $2$\textsuperscript{th} coordinate in the block $x_j$ is at least
  \begin{align*}
    \min\left\{\bar{t}_2, V^{-1}_{i_{2,j}}\left(\eta_{j,2} + V_{i_{2,j}}(\bar{t}_1)\right)\right\}
  \end{align*}
  seconds, where $\eta_{j,2}$ is a geometric random variable with the probability $p_{2,i_{2,j}},$ because either the algorithm returns $t^k \geq \bar{t}_2,$ or it keeps returning $t^k < \bar{t}_2,$ but then $A$ should first progress to the $1$\textsuperscript{th} coordinate, which takes at least $\bar{t}_1$ seconds, and then should calculate at least $\eta_{j,2}$ stochastic gradients. This will take at least 
  \begin{align*}
    &\min\left\{t \geq 0 \, : \, \flr{V_{i_{2,j}}(t) - V_{i_{2,j}}(\bar{t}_1)} \geq \eta_{j,2}\right\} \\
    &\overset{(\textnormal{cont. of }V_{i_{2,j}})}{=}\min\left\{t \geq 0 \, : \, V_{i_{2,j}}(t) - V_{i_{2,j}}(\bar{t}_1) = \eta_{j,2}\right\} \\
    &\overset{\eqref{eq:inv}}{=}V^{-1}_{i_{2,j}}\left(\eta_{j,2} + V_{i_{2,j}}(\bar{t}_1)\right)
  \end{align*}
  seconds. Notice that the parameter of the geometric random variable $\eta_{j,2}$ depends on the previous randomness.

  In the case \textbf{Opt. 1}, we can only conclude that the algorithm $A$ will require at least $\bar{t}_0 \equiv 0$ seconds to get a non-zero value in the $T$\textsuperscript{th} coordinate. In the case \textbf{Opt. 2}, we have better guarantees and can infer that the algorithm $A$ will require at least $\bar{t}_1 \geq \bar{t}_1$ seconds to get a non-zero value in the $T$\textsuperscript{th} coordinate because the inequality $V^{-1}_{i_{1,j}}\left(\eta_{j,1}\right) \geq \bar{t}_1$ holds. Hence, the condition in \begin{NoHyper}Line~\ref{line:iforig}\end{NoHyper} of Alg.~\ref{alg:resisting} determines a necessary time to get the $T$\textsuperscript{th} with a non-zero value.

  For all $j \in [m],$ we have the following Markov process that generalizes our previous discussion.
  \begin{algorithm}[H]
    \caption{Markov process in the $j$\textsuperscript{th} block}
    \label{alg:markov_process}
    \begin{algorithmic}[1]
    \STATE Current time window $w_m = 1$
    \FOR{$m = 1, \dots, T$}
    \STATE Find $i_{w_m,j}$ such that $s_{w_m,i_{w_m,j}-1} \leq j < s_{w_m,i_{w_m,j}}$
    \STATE Draw an infinite i.i.d. sequence $\{\xi_{j,m,s}\}_{s=1}^{\infty}$ from $\textnormal{Bernoulli}(p_{w_m,i_{w_m,j}})$
    \STATE Find the first moment when $\xi_{j,m,s} = 1,$ i.e., $\eta_{j,m} = \inf\{s \geq 1 \,:\, \xi_{j,m,s} = 1\}$ \\
    % $\eta \sim \textnormal{Geometric}(p_{w,i_{w,j}})$ ``defined'' by $\xi_{j,m}$ in \eqref{eq:JizJACFEaGQaVyyLArn_random}
    \IF{$V^{-1}_{i_{w_m,j}}\left(\eta_{j,m} + V_{i_{w_m,j}}(\bar{t}_{w_m - 1})\right) \geq \bar{t}_{w_m}$} \alglinelabel{line:if}
    \STATE $w_{m+1} \leftarrow w_{m} + 1$
    \ELSE
    \STATE $w_{m+1} \leftarrow w_{m}$
    \ENDIF
    \ENDFOR
    \STATE \textbf{Return: } $\bar{t}_{(w_T - 1)}$ is a necessary time to get the $T$\textsuperscript{th} non-zero coordinate in the $j$\textsuperscript{th} block
    \end{algorithmic}
  \end{algorithm}

  The provided random Markov process determines the time $\bar{t}_{(w_T - 1)}$ required to get the $T$\textsuperscript{th} non-zero coordinate in the $j$\textsuperscript{th} block.

  For all $j \in [m], m \in [T],$ $\eta_{j,m}$ has the geometric distribution with the parameter $p_{w_m,i_{w_m,j}},$ which depends only on the previous random variables $\eta_{j,1}, \dots, \eta_{j,m - 1}.$ Therefore, we can use Lemma~\ref{lemma:concentration_sum} and get
  \begin{align*}
    \Prob{\sum_{m=1}^{T} \mathbbm{1}\left[\eta_{j,m} > \frac{1}{4 p_{w_m,i_{w_m,j}}}\right] \leq \frac{T}{2} + \log \delta} \leq \delta
  \end{align*}
  for all $\delta \in (0, 1].$ The last inequality means that with a probability at least $\nicefrac{3}{4},$ there exist $1 \leq m_1 < m_2 < \dots < m_{\flr{\frac{T - 2}{2}}} \leq T$ such that 
  \begin{align}
  \label{eq:GcvkzDBZNbH}
  \eta_{j, m_k} > \frac{1}{4 p_{w_{m_k},i_{w_{m_k},j}}} \geq \frac{1}{8 p_{w_{m_k},i_{w_{m_k},j}}}
  \end{align}
  for all $k \in \left[\flr{\frac{T - 2}{2}}\right].$

  Due to \eqref{eq:uOIGCRiWeKzxBT_random} and \eqref{eq:JpjVFT_random}, we have
  \begin{align*}
    p_{w,i} \eqdef \min\left\{\frac{4 \varepsilon \gamma_{\infty}^2 a_{w,i} n^2}{\sigma^2 S}, 1\right\}.
  \end{align*}

  Recall that $\{\bar{t}_w\}_{w \in [\bar{T}]},$$\{s_{w,i}\}_{w \in [\bar{T} + 1], i \in [n]},$ and $S \in \N$ are free parameters with the only conditions \eqref{eq:BZjAsfDsrOOEsFIQk} and \eqref{eq:BZjAsfDsrOOEsFIQkk}. Therefore, we can use Lemma~\ref{lemma:params} with $K = 1$ and ensure that there exist parameters such that

  \begin{align*}
    V^{-1}_{i}\left(\frac{1}{8 p_{w,i}} + V_{i}(\bar{t}_{w-1})\right) \geq \bar{t}_w.
  \end{align*}
  for all $w \in [T], i \in [n].$ Putting the last inequality, \eqref{eq:GcvkzDBZNbH}, and \begin{NoHyper}Line~\ref{line:if}\end{NoHyper} of Alg.~\ref{alg:markov_process} together, we can conclude that, with a probability at least $\nicefrac{3}{4},$ the value of $w_T - 1$ is greater or equal to $\flr{\frac{T - 2}{2}}$ since the condition in \begin{NoHyper}Line~\ref{line:if}\end{NoHyper} of Alg.~\ref{alg:markov_process} will hold at least $\flr{\frac{T - 2}{2}}$ times. 
