\begin{lemma}
  \label{lemma:min_inf}
  Let $V_i \,:\, \R^{\infty}_{+} \to \R^{\infty}_{+}$ is a continuous and non-decreasing function for all $i \in [n].$ For all $\eta, b_1,\dots,b_n \in \R^{\infty}_{+},$ the minimums of the sets 
  \begin{align*}
    \left\{t \geq 0 \, : \, \sum_{i=1}^n \flr{V_i(t) - b_i} \geq \eta\right\}
  \end{align*}
  and 
  \begin{align*}
    \left\{t \geq 0 \, : \, \left(\frac{1}{n} \sum_{i=1}^n \frac{1}{\flr{V_i(t) - b_i}}\right)^{-1} \geq \eta\right\}
  \end{align*}
  exist, considering the convention $\min \{\emptyset\} = \infty.$
  % \begin{align}
  %   \label{eq:UneoeLq}
  %   \inf\left\{t \geq 0 \, : \, \sum_{i=1}^n \flr{V_i(t)} \geq \eta\right\} = \min\left\{t \geq 0 \, : \, \sum_{i=1}^n \flr{V_i(t)} \geq \eta\right\}.
  % \end{align}
\end{lemma}

\begin{proof}
  We now focus on the first set. If the set is empty, then the minimum is $\infty$ by the convention.
  Otherwise, let us define 
  \begin{align*}
    \underline{t} \eqdef \inf\left\{t \geq 0 \, : \, \sum_{i=1}^n \flr{V_i(t) - b_i} \geq \eta\right\} < \infty.
  \end{align*}

  If the minimum does not exist, then
  % because 
  \begin{align*}
    \sum_{i=1}^n \flr{V_i(\underline{t}) - b_i} < \eta.
  \end{align*}
  For all $i \in [n],$ the functions $V_i$ is continuous and non-decreasing meaning that there exists $\delta_i > 0$ such that
  \begin{align*}
    \flr{V_i(\underline{t}) - b_i} = \flr{V_i(\underline{t} + \delta) - b_i}.
  \end{align*}
  for all $0 \leq \delta \leq \delta_i.$ Let us take $\delta = \min\limits_{i \in [n]} \delta_i > 0,$ then
  \begin{align*}
    \sum_{i=1}^n \flr{V_i(\underline{t} + \delta) - b_i} = \sum_{i=1}^n \flr{V_i(\underline{t}) - b_i} < \eta.
  \end{align*}
  This contradicts the fact that $\underline{t}$ is the infimum. The reasoning for the second set is the same.
\end{proof}

\begin{lemma}
  \label{lemma:concentration_sum}
  Let $T \geq 1$ and $\{\eta_i\}_{i=1}^{T}$ are geometric random variables such that given $\eta_1, \dots, \eta_{i-1},$ $\eta_i~\sim~\textnormal{Geometric}(p_{i,\eta_1,\dots,\eta_{i-1}})$ and the probability $p_{i,\eta_1,\dots,\eta_{i-1}} \in (0, 1]$ depends only on $\eta_1,\dots,\eta_{i-1}$ for all $i \in [T].$
  Then \begin{align*}
    \Prob{\sum_{i=1}^{T} \mathbbm{1}\left[\eta_i > \frac{1}{4 p_{i,\eta_1,\dots,\eta_{i-1}}}\right] \leq \frac{T}{2} + \log \delta} \leq \delta
  \end{align*}
  for all $\delta \in (0, 1].$
\end{lemma}

\begin{proof}
  Let us consider the simplified notation $p_i \equiv p_{i,\eta_1,\dots,\eta_{i-1}}$ and take any $\bar{T}, s > 0.$ 
  Using Chernoff's method, we get
  \begin{equation}
  \begin{aligned}
    \label{eq:CCIRBdDXoD}
    \Prob{\sum_{i=1}^{T} \mathbbm{1}\left[\eta_i > \frac{1}{4 p_i}\right] \leq \bar{T}} 
    &= \Prob{- s \sum_{i=1}^{T} \mathbbm{1}\left[\eta_i > \frac{1}{4 p_i}\right] \geq - s\bar{T}} \\
    &\leq e^{s\bar{T}}\Exp{e^{-s \sum_{i=1}^{T} \mathbbm{1}\left[\eta_i > \frac{1}{4 p_i}\right]}} \\
    &= e^{s\bar{T}}\Exp{\prod_{i=1}^{T} \ExpCond{e^{-s \mathbbm{1}\left[\eta_i > \frac{1}{4 p_i}\right]}}{\eta_1, \dots, \eta_{i - 1}}},
  \end{aligned}
  \end{equation}
  where we use the definition of conditional expectation.

  % where we use the independence of $\{\eta_i\}.$ 
  For all $i \in [T],$ we now consider the $i$\textsuperscript{th} expectation separately:
  \begin{align*}
    &\ExpCond{e^{-s \mathbbm{1}\left[\eta_i > \frac{1}{4 p_i}\right]}}{\eta_1, \dots, \eta_{i - 1}} \\
    &= \ProbCond{\eta_i \leq \frac{1}{4 p_i}}{\eta_1, \dots, \eta_{i - 1}} + e^{-s} \ProbCond{\eta_i > \frac{1}{4 p_i}}{\eta_1, \dots, \eta_{i - 1}} \\
    &= (1 - e^{-s})\ProbCond{\eta_i \leq \frac{1}{4 p_i}}{\eta_1, \dots, \eta_{i - 1}} + e^{-s}.
  \end{align*}

  Due the assumption of our theorem, given $\eta_1, \dots, \eta_{i - 1},$ $\eta_i$ is a geometric random variable with the parameter $p_i \equiv p_{i,\eta_1,\dots,\eta_{i-1}}.$ Therefore
  \begin{align*}
    &\ExpCond{e^{-s \mathbbm{1}\left[\eta_i > \frac{1}{4 p_i}\right]}}{\eta_1, \dots, \eta_{i - 1}} = (1 - e^{-s})\left(1 - (1 - p_i)^{\flr{\frac{1}{4 p_i}}}\right) + e^{-s},
  \end{align*}
  where $1 - (1 - p_i)^{\flr{\frac{1}{4 p_i}}} = 0$ if $p_i = 1$ and $\flr{\frac{1}{4 p_i}} = 0.$ Since $1 - (1 - p)^{\flr{S}} \leq p \flr{S}$ for all $p \in (0, 1]$ and $S \geq 0,$ we get 
  \begin{align*}
    \ExpCond{e^{-s \mathbbm{1}\left[\eta_i > \frac{1}{4 p_i}\right]}}{\eta_1, \dots, \eta_{i - 1}} 
    &\leq (1 - e^{-s}) p_i \flr{\frac{1}{4 p_i}} + e^{-s} \\
    &\leq (1 - e^{-s}) p_i \times \frac{1}{4 p_i} + e^{-s} = (1 - e^{-s}) \frac{1}{4} + e^{-s}.
  \end{align*}

  Let us take $s = 1,$ then
  \begin{align*}
    &\ExpCond{e^{-s \mathbbm{1}\left[\eta_i > \frac{1}{4 p_i}\right]}}{\eta_1, \dots, \eta_{i - 1}} \leq (1 - e^{-1}) \frac{1}{4} + e^{-1} \leq e^{-1/2}.
  \end{align*}

  We substitute the last inequality and the chosen value of $s$ to \eqref{eq:CCIRBdDXoD} and get
  \begin{align*}
    \Prob{\sum_{i=1}^{T} \mathbbm{1}\left[\eta_i > \frac{1}{4 p_i}\right] \leq \bar{T}} \leq e^{\bar{T} - \frac{T}{2}}.
  \end{align*}

  For all $\delta \in (0, 1],$ we can take 
  \begin{align*}
    \bar{T} = \frac{T}{2} + \log \delta
  \end{align*}

  to ensure that 

  \begin{align*}
    \Prob{\sum_{i=1}^{T} \mathbbm{1}\left[\eta_i > \frac{1}{4 p_i}\right] \leq \frac{T}{2} + \log \delta} \leq \delta.
  \end{align*}
\end{proof}

\begin{restatable}{lemma}{LEMMAMANYGEOM}
  \label{lemma:many_geom}
  Let $\eta_{1,1}, \dots, \eta_{1,K} \sim \textnormal{Geometric}(p_1),$ $\eta_{2,1}, \dots, \eta_{2,K} \sim \textnormal{Geometric}(p_2),$ \dots, $\eta_{\bar{T},1}, \dots, \eta_{\bar{T},K} \sim \textnormal{Geometric}(p_{\bar{T}})$ are mutually independent geometric random variables. Then
  \begin{align*}
    \Prob{\bigcup_{k \in [\bar{T}]} \left\{\sum_{j=1}^{K} \eta_{k,j} \leq \frac{K}{8 p_k}\right\}} \leq \bar{T} e^{- K / 2}.
  \end{align*}
\end{restatable}

\begin{proof}
  Let us fix any $a_k \geq 0$ for all $k \in [\bar{T}].$ Using the union bound, we get
  \begin{align}
    \label{eq:PSlfIjXYcoVVpkDVxSt}
    \Prob{\bigcup_{k \in [\bar{T}]} \left\{\sum_{j=1}^{K} \eta_{k,j} \leq a_k\right\}} \leq \sum_{k=1}^{\bar{T}} \Prob{\sum_{j=1}^{K} \eta_{k,j} \leq a_k}.
  \end{align}
  For all $k \in [\bar{T}]$ and $s > 0,$ we obtain the following series of inequalities:
  \begin{align*}
    \Prob{\sum_{j=1}^{K} \eta_{k,j} \leq a_k} 
    &=\Prob{- s \sum_{j=1}^{K} \eta_{k,j} \geq -s a_k} =\Prob{e^{- s \sum_{j=1}^{K} \eta_{k,j}} \geq e^{-s a_k}} \\
    &\leq e^{s a_k} \Exp{e^{- s \sum_{j=1}^{K} \eta_{k,j}}},
  \end{align*}
  where we use Markov's inequality. Since the random variables are mutually independent, we have
  \begin{align*}
    \Prob{\sum_{j=1}^{K} \eta_{k,j} \leq a_k} 
    &\leq e^{s a_k} \left(\Exp{e^{- s \eta_{k,1}}}\right)^K = e^{s a_k} \left(\frac{p_k}{e^{s} - (1 - p_k)}\right)^K,
  \end{align*}
  where we use the moment-generating function of the geometric random variables. Since $p_k \geq 0$ and $e^s \geq 1 + s$ for all $s \in \R,$ we get
  \begin{align*}
    \Prob{\sum_{j=1}^{K} \eta_{k,j} \leq a_k} 
    \leq e^{s a_k} \left(\frac{p_k}{s}\right)^K.
  \end{align*}
  Let us take $s = 4 p_k$ to ensure that
  \begin{align*}
    \Prob{\sum_{j=1}^{K} \eta_{k,j} \leq a_k} 
    \leq e^{4 p_k a_k - K}.
  \end{align*}
  We can take $a_k = \frac{K}{8 p_k}$ to get
  \begin{align*}
    \Prob{\sum_{j=1}^{K} \eta_{k,j} \leq \frac{K}{8 p_k}} \leq e^{- K / 2}.
  \end{align*}
  It is left to substitute the last inequality to \eqref{eq:PSlfIjXYcoVVpkDVxSt}.
\end{proof}
    \begin{lemma}
      \label{lemma:params}
      For all $\bar{T}, K \in \N,$ there exist non-negative parameters $\{\bar{t}_w\}_{w \in [\bar{T}]},$$\{s_{w,i}\}_{w \in [\bar{T} + 1], i \in [n]},$ and $S \in \N$ such that
      \begin{enumerate}
      \item 
      \begin{equation}
