        s_{w,0} \equiv 1 \leq s_{w,1} \leq \dots \leq s_{w,n - 1} \leq s_{w,n} \equiv S + 1 \quad \forall w \in [\bar{T} + 1], \\
        \bar{t}_0 \equiv 0 \leq \bar{t}_1 \leq \dots \leq \bar{t}_{\bar{T}} \leq \bar{t}_{\bar{T} + 1} \equiv \infty.
