    \end{align*}
    for all $w \in [\bar{T}].$
    Due to \eqref{eq:uOIGCRiWeKzxBT_new}, it is sufficient to find $\{a_{w,i}\},$ $\{\bar{t}_w\},$ and $S$ such that \eqref{eq:lOuQCvNGUaR} holds and
    \begin{align}
      \label{eq:fcfmDYHrdNhCex}
      &\min\left\{\frac{a_{w,i} n^2 4 \varepsilon \gamma_{\infty}^2}{S \sigma^2}, 1\right\} \nonumber \\
      &\overset{\eqref{eq:lOuQCvNGUaR}}{=} \min\left\{\frac{a_{w,i} n^2 4 \varepsilon \gamma_{\infty}^2}{\sum_{i=1}^n a_{w,i} \sigma^2}, 1\right\} < \frac{K}{8 (V_{i}(\bar{t}_w) - V_{i}(\bar{t}_{w-1}))}
    \end{align}
    for all $i \in [n]$ and for all $w \in [\bar{T}].$ \\
    Assume that $\bar{t}_{w-1}$ is defined ($\bar{t}_{0} \equiv 0$), and let us now consider $w \in [\bar{T}].$\\
    Let us define
    \begin{align}
      \label{eq:zZQIJohzAKjLIzyPmU}
      \bar{t}_{w}^1 \eqdef \max\limits_{j \in [n]} V^{-1}_j\left(\frac{K}{16} + V_j(\bar{t}_{w - 1})\right)
    \end{align}
    and
    \begin{align}
      \label{eq:ginRrbVSB}
      \bar{t}_w^2 \eqdef \min \left\{t \geq 0 \,:\, \sum_{i=1}^n \frac{K \sigma^2}{n^2 4 \varepsilon \gamma_{\infty}^2 \left(V_{i}\left(t\right) - V_{i} (\bar{t}_{w - 1})\right)} = 64\right\}.
    \end{align}
    \textbf{Opt. 1:} If $\bar{t}_{w}^1 > \bar{t}_w^2,$ then we take $\bar{t}_{w} = \bar{t}_{w}^1,$ $\bar{a}_{w,i} \eqdef 0$ for all $i \neq j^*,$ and $\bar{a}_{w,j^*} \eqdef 1,$ where 
    \begin{align}
      \label{eq:OKWUJhCJvikNrqHw}
