    \textbf{Opt. 2:} If $\bar{t}_{w}^1 \leq \bar{t}_w^2,$ then we take $\bar{t}_{w} = \bar{t}_{w}^2,$ and \footnote{$V_{i}\left(\bar{t}_w\right) > V_{i} (\bar{t}_{w - 1})$ for all $i \in [n]$ since $\bar{t}_{w} \geq \bar{t}_w^1$ and $V_i(\bar{t}_{w}) \geq \frac{K}{16} + V_i(\bar{t}_{w - 1})$ for all $i \in [n],$ due to \eqref{eq:zZQIJohzAKjLIzyPmU} and the definition \eqref{eq:inv}.} 
