    \begin{lemma}\citep{tyurin2024freya}[Section K]\label{lemma:techn1}
      Consider a sequence $\infty > v_1\geq \ldots \geq v_n$ and fix some $S>0$. For all $j \in [n]$, define $$g(j) \eqdef \left(\sum_{i=1}^j v_i\right)^{-1} \left(S + j\right).$$ 
      \begin{enumerate}
          \item Let $j^*_{\max}$ be the largest index such that $\min\limits_{j \in [n]} g(j) = g(j^*_{\max}).$ For $j^*_{\max} < n,$ we have
          \begin{align*}
              \min_{j \in [n]} g(j) < \frac{1}{v_{(j^*_{\max} + 1)}}.
          \end{align*}
          \item Let $j^*$ be any index such that $\min\limits_{j \in [n]} g(j) = g(j^*).$ For $j^* < n,$ we have
          \begin{align*}
              \min_{j \in [n]} g(j) \leq \frac{1}{v_{(j^* + 1)}}.
          \end{align*}
          \item Let $j^*_{\min}$ be the smallest index such that $\min\limits_{j \in [n]} g(j) = g(j^*_{\min})$. Then
          \begin{align*}
              \frac{1}{v_{j^*_{\min}}} < \min_{j \in [n]} g(j).
          \end{align*}
          \item Let $j^*$ be any index such that $\min\limits_{j \in [n]} g(j) = g(j^*).$ Then
          \begin{align*}
              \frac{1}{v_{j^*}} \leq \min_{j \in [n]} g(j).
          \end{align*}
      \end{enumerate}
  \end{lemma}

