  \section{Convex Setting}
  \label{sec:convex}

  In the convex setting, the time complexities do not change significantly in a conceptual sense compared to the nonconvex case. Therefore, we will provide a somewhat less detailed description in this section. The obtained time complexities also hinge on the sequences \eqref{eq:homog_compl} and \eqref{eq:upper_bound}. The only difference is the number of iterations that the methods do in each particular setup. 

  Using the same reasoning as in other sections and \citep{tyurin2023optimal}[Section B], we conjecture that the following results are optimal up to constant factors. It is sufficient to use an appropriate ``difficult'' function \citep{guzman2015lower,nesterov2018lectures,woodworth2018graph} designed for the convex domain instead of \eqref{eq:worst_case}.

  We use the following assumptions:
  \begin{assumption}
    \label{ass:convex}
    The function $f$ is convex and attains a minimum at some point $x^* \in \R^d.$
  \end{assumption}
  \begin{assumption}
    \label{ass:lipschitz_constant_function}
    The function $f$ is $M$--Lipschitz, i.e., $$\abs{f(x) - f(y)} \leq M \norm{x - y}, \quad \forall x, y \in \R^d$$ for some $M \in (0, \infty].$
  \end{assumption}

  \begin{assumption}[Homogeneous setup]
    \label{ass:stochastic_variance_bounded_convex}
    For all $i \in [n],$ worker $i$ can only calculate $\nabla f(x;\xi).$ For all $x \in \R^d,$ stochastic (sub)gradients $\nabla f(x;\xi)$ are unbiased and are $\sigma^2$-variance-bounded, i.e.,
    $\ExpSub{\xi}{\nabla f(x;\xi)} \in \partial f(x)$ and 
    $\ExpSub{\xi}{\norm{\nabla f(x;\xi) - \ExpSub{\xi}{\nabla f(x;\xi)}}^2} \leq \sigma^2,$ where $\sigma^2 \geq 0.$
  \end{assumption} 

  \begin{assumption}[Heterogeneous setup]
    \label{ass:stochastic_variance_bounded_convex_heter}
    For all $i \in [n],$ worker $i$ can only calculate $\nabla f_i(x;\xi_i).$ For all $x \in \R^d, i \in [n]$ stochastic (sub)gradients $\nabla f_i(x;\xi_i)$ are unbiased and are $\sigma^2$-variance-bounded, i.e.,
    $\ExpSub{\xi_i}{\nabla f_i(x;\xi_i)} \in \partial f_i(x)$ and 
    $\ExpSub{\xi_i}{\norm{\nabla f_i(x;\xi_i) - \ExpSub{\xi_i}{\nabla f_i(x;\xi_i)}}^2} \leq \sigma^2,$ where $\sigma^2 \geq 0.$
  \end{assumption} 

  We consider \emph{four} cases.

  \subsection{Homogeneous setup and nonsmooth case}

\begin{restatable}{theorem}{THEOREMSGDHOMOGCONVEX}[\citep{tyurin2023optimal}]
  \label{thm:sgd_homog_convex}
Let Assumptions~\ref{ass:convex}, \ref{ass:lipschitz_constant_function} and \ref{ass:stochastic_variance_bounded_convex} hold. Choose any $\varepsilon > 0.$ Let us take the batch size $S = \max\left\{\left\lceil\nicefrac{\sigma^2}{M^2}\right\rceil, 1\right\},$
  stepsize $\gamma = \frac{\varepsilon}{M^2 + \sigma^2 / S} \in \left[\frac{\varepsilon}{2 M^2}, \frac{\varepsilon}{M^2}\right]$ in Method~\ref{alg:alg_server}.
  Then after $K \geq \nicefrac{2 M^2 R^2}{\varepsilon^2}$
  iterations the method guarantees $\Exp{f(\widehat{x}^K)} - f(x^*) \leq \varepsilon,$ where $\widehat{x}^K = \frac{1}{K} \sum_{k=0}^{K-1} x^k$ and $R = \norm{x^* - x^{0}}.$
\end{restatable}

\begin{restatable}{theorem}{THEOREMMAINSTATICTIMECONVEX}
  \label{cor:convex_non_smooth}
  Consider the assumptions and the parameters from Theorem~\ref{thm:sgd_homog_convex}, plus Assumption~\ref{ass:speed}. Then Method~\ref{alg:alg_server} (\algname{Rennala SGD}) converges after at most $\bar{t}_{\ceil{\frac{2 M^2 R^2}{\varepsilon^2}}}$ seconds, where the sequence $\bar{t}_k$ is defined in \eqref{eq:homog_compl}.
\end{restatable}

\begin{proof}
  The proof is identical to the proof of Theorem~\ref{cor:max_time_params}.
\end{proof}

\subsection{Homogeneous setup and smooth case}
\label{sec:convex_smooth_homog}
In the homogeneous and smooth case, we can use an accelerated technique \citep{nesterov1983method,lan2020first}. Instead of \begin{NoHyper}Line~\ref{alg:step_homog}\end{NoHyper} of Method~\ref{alg:alg_server}, we use the following steps suggested by \citet{lan2020first}:
\begin{equation}
\begin{aligned}
    &\gamma_{k+1} = \gamma \cdot (k + 1), \quad \alpha_{k+1} = 2 / (k+2) \\
    &y^{k+1} = (1 - \alpha_{k+1}) x^k + \alpha_{k+1} u^k, \qquad (u^0 = x^0)\\
    &u^{k+1} = u^{k} - \frac{\gamma_{k+1}}{s^k}g^k, \\
    &x^{k+1} = (1 - \alpha_{k+1}) x^k + \alpha_{k+1} u^{k+1}.
    \label{eq:sub_steps_acc}
\end{aligned}
\end{equation}
A new method with these steps is called the \algname{Accelerated Rennala SGD} method \citep{tyurin2023optimal}. 
\begin{restatable}{theorem}{THEOREMSGDHOMOGCONVEXACC}[\citep{tyurin2023optimal}]
  \label{thm:sgd_homog_convex_acc}
  Let Assumptions~\ref{ass:convex}, \ref{ass:lipschitz_constant} and \ref{ass:stochastic_variance_bounded} hold. Choose any $\varepsilon > 0.$ Let us take the batch size $S = \max\left\{\left\lceil (\sigma^2 R) / (\varepsilon^{3/2} \sqrt{L})\right\rceil, 1\right\},$
  and $\gamma = \min\left\{\frac{1}{4L}, \left[\frac{3 R^2 S}{4 \sigma^2 (K + 1)(K + 2)^2}\right]^{1/2}\right\}$ in Accelerated Method~\ref{alg:alg_server} (\algname{Accelerated Rennala SGD}),
  then after $K \geq \frac{8 \sqrt{L} R}{\sqrt{\varepsilon}}$
  iterations the method guarantees that $\Exp{f(x^K)} - f(x^*) \leq \varepsilon,$ where $R = \norm{x^* - x^{0}}.$
\end{restatable}

\begin{theorem}
  \label{cor:convex_smooth}
  Consider the assumptions and the parameters from Theorem~\ref{thm:sgd_homog_convex_acc}, plus Assumption~\ref{ass:speed}. Then Accelerated Method~\ref{alg:alg_server} (\algname{Accelerated Rennala SGD}) converges after at most $\bar{t}_{\ceil{\frac{8 \sqrt{L} R}{\sqrt{\varepsilon}}}}$ seconds, where the sequence $\bar{t}_k$ is defined in \eqref{eq:homog_compl}.
\end{theorem}

\begin{proof}
  The proof is identical to the proof of Theorem~\ref{cor:max_time_params}.
\end{proof}

\subsection{Heterogeneous setup and nonsmooth case}

Consider the heterogeneous setup discussed in Section~\ref{sec:introduction}.

\begin{restatable}{theorem}{THEOREMSGDHETERCONVEX}
  \label{thm:sgd_heter_convex}
  Let Assumptions~\ref{ass:convex}, \ref{ass:lipschitz_constant_function}, and \ref{ass:stochastic_variance_bounded_convex_heter} hold. Choose any $\varepsilon > 0.$ Let us take $S = \max\left\{\left\lceil\nicefrac{\sigma^2}{M^2}\right\rceil, n\right\},$ and
  $\gamma = \frac{\varepsilon}{M^2 + \sigma^2 / S} \in \left[\frac{\varepsilon}{2 M^2}, \frac{\varepsilon}{M^2}\right]$ in Method~\ref{alg:alg_server_heterog},
  then after $K \geq \nicefrac{2 M^2 R^2}{\varepsilon^2}$
  iterations the method guarantees that $\Exp{f(\widehat{x}^K)} - f(x^*) \leq \varepsilon,$ where $\widehat{x}^K = \frac{1}{K} \sum_{k=0}^{K-1} x^k$ and $R = \norm{x^* - x^{0}}.$
\end{restatable}

\begin{proof}
  Notice that \algname{Malenia SGD} is equivalent to the classical \algname{SGD} method with the step
  \begin{align*}
    x^{k+1} = x^k - \gamma \frac{1}{n} \sum_{j=1}^n \frac{1}{B_j} \sum_{i=1}^{B_j} \nabla f_j(x^k;\xi^k_{j,i}),
  \end{align*}
  where the variance of the unbiased gradient estimator can be bounded in the following way:
  \begin{align*}
    \ExpSub{\xi^k}{\norm{\frac{1}{n} \sum_{j=1}^n \frac{1}{B_j} \sum_{i=1}^{B_j} \nabla f_j(x^k;\xi^k_{j,i}) - \nabla f(x^k)}^2} \leq \frac{\sigma^2}{n^2} \left(\sum_{j=1}^n \frac{1}{B_j}\right).
  \end{align*}
  In Method~\ref{alg:alg_server_heterog}, we ensure that $\left(\sum_{j=1}^n \frac{1}{B_j}\right) \leq \frac{n^2}{S}.$ Therefore
  \begin{align*}
    \ExpSub{\xi^k}{\norm{\frac{1}{n} \sum_{j=1}^n \frac{1}{B_j} \sum_{i=1}^{B_j} \nabla f_j(x^k;\xi^k_{j,i}) - \nabla f(x^k)}^2} \leq \frac{\sigma^2}{S}.
  \end{align*}
  Thus, we can use the classical result from the literature (e.g. \citep{lan2020first}). We get
  \begin{align*}
      \Exp{f(\widehat{x}^K)} - f(x^*) \leq \varepsilon
  \end{align*}
  if $$K \geq \frac{2 M^2 \norm{x^* - x^{0}}^2}{\varepsilon^2} \geq \frac{(M^2 + \frac{\sigma^2}{S})\norm{x^* - x^{0}}^2}{\varepsilon^2}$$ for the stepsize $$\gamma = \frac{\varepsilon}{M^2 + \frac{\sigma^2}{S}} \in \left[\frac{\varepsilon}{2 M^2}, \frac{\varepsilon}{M^2}\right],$$
  where we use the fact that $S \geq \nicefrac{\sigma^2}{M^2}.$
\end{proof}

\begin{theorem}
  Consider the assumptions and the parameters from Theorem~\ref{thm:sgd_heter_convex}, plus Assumption~\ref{ass:speed}. Then Method~\ref{alg:alg_server_heterog} (\algname{Malenia SGD}) converges after at most $\bar{t}_{\ceil{\frac{2 M^2 R^2}{\varepsilon^2}}}$ seconds, where the sequence $\bar{t}_k$ is defined in \eqref{eq:upper_bound}.
\end{theorem}

\begin{proof}
  The proof is identical to the proof of Theorem~\ref{cor:max_time_params_heter}.
\end{proof}

\subsection{Heterogeneous setup and smooth case}

Using the same idea as in Section~\ref{sec:convex_smooth_homog}, we will modify \algname{Malenia SGD} and, instead of \begin{NoHyper}Line~\ref{line:step_heter}\end{NoHyper} from Algorithm~\ref{alg:alg_server_heterog}, we use the lines \eqref{eq:sub_steps_acc}. Such a method is called \algname{Accelerated Malenia SGD}.

\begin{restatable}{theorem}{THEOREMSGDHETERCONVEXACC}
  \label{thm:sgd_heter_convex_acc}
  Let Assumptions~\ref{ass:convex} and \ref{ass:lipschitz_constant}, and \ref{ass:stochastic_variance_bounded_heter} hold. Choose any $\varepsilon > 0.$ Let us take $S = \max\left\{\left\lceil (\sigma^2 R) / (\varepsilon^{3/2} \sqrt{L})\right\rceil, n\right\},$
  and $\gamma = \min\left\{\frac{1}{4L}, \left[\frac{3 R^2 S}{4 \sigma^2 (K + 1)(K + 2)^2}\right]^{1/2}\right\}$ in Accelerated Method~\ref{alg:alg_server_heterog} (\algname{Accelerated Malenia SGD}),
  then after $K \geq \frac{8 \sqrt{L} R}{\sqrt{\varepsilon}}$
  iterations the method guarantees that $\Exp{f(x^K)} - f(x^*) \leq \varepsilon,$ where $R = \norm{x^* - x^{0}}.$
\end{restatable}

\begin{proof}
  \algname{Accelerated Malenia SGD} is equivalent to the classical accelerated stochastic gradient method with a mini-batch from \citep{lan2020first}. The proof repeats the proofs of Theorem~\ref{thm:sgd_homog_convex_acc} and Theorem~\ref{thm:sgd_heter_convex}.
\end{proof}

\begin{theorem}
  Consider the assumptions and the parameters from Theorem~\ref{thm:sgd_heter_convex_acc}, plus Assumption~\ref{ass:speed}. Then Accelerated Method~\ref{alg:alg_server_heterog} (\algname{Accelerated Malenia SGD}) converges after at most $\bar{t}_{\ceil{\frac{8 \sqrt{L} R}{\sqrt{\varepsilon}}}}$ seconds, where the sequence $\bar{t}_k$ is defined in \eqref{eq:upper_bound}.
\end{theorem}

\begin{proof}
  The proof is identical to the proof of Theorem~\ref{cor:max_time_params_heter}.
\end{proof}

