      &\leq \min\left\{\frac{1}{n} \sum_{i=1}^n \frac{1}{2 v_i \left(\frac{1}{n} \sum_{i=1}^n \frac{1}{v_i}\right)\frac{\sigma^2}{n \varepsilon}}, 1\right\} = \min\left\{\frac{n \varepsilon}{2 \sigma^2}, 1\right\}.
    \end{align*}
    Thus $\bar{\delta} \leq \bar{\delta}_{4}.$ On the other hand, let us show that $\frac{1}{n} \sum_{i=1}^n \flr{v_i \delta_{\nicefrac{1}{4}}}^{-1} > \min\left\{\nicefrac{n \varepsilon}{2 \sigma^2}, 1\right\}.$ If $\max_{i \in [n]} \nicefrac{1}{v_i} > \left(\frac{1}{n} \sum_{i=1}^n \nicefrac{1}{v_i}\right)\nicefrac{\sigma^2}{n \varepsilon},$ then $\delta_{\nicefrac{1}{4}} < \nicefrac{1}{2} \max_{i \in [n]} \nicefrac{1}{v_i},$ $\flr{v_j \delta_{\nicefrac{1}{4}}} = 0$ for $j = \arg\max_{i \in [n]} \nicefrac{1}{v_i},$ and $\frac{1}{n} \sum_{i=1}^n \flr{v_i \delta_{\nicefrac{1}{4}}}^{-1} = \infty \geq \nicefrac{n \varepsilon}{2 \sigma^2}.$ If $\max_{i \in [n]} \nicefrac{1}{v_i} \leq \left(\frac{1}{n} \sum_{i=1}^n \nicefrac{1}{v_i}\right)\nicefrac{\sigma^2}{n \varepsilon},$ then since $\flr{x} \leq x$ for all $x \geq 0,$ we get
    \begin{align*}
      \frac{1}{n} \sum_{i=1}^n \flr{v_i \delta_{\nicefrac{1}{4}}}^{-1} \geq \frac{1}{n} \sum_{i=1}^n (v_i \delta_{\nicefrac{1}{4}})^{-1} \overset{\eqref{eq:neZpKwdjesRZeQSQ}}{\geq} \frac{1}{n} \sum_{i=1}^n \frac{2}{v_i \left(\frac{1}{n} \sum_{i=1}^n \frac{1}{v_i}\right)\frac{\sigma^2}{n \varepsilon}} > \frac{n \varepsilon}{2 \sigma^2}.
    \end{align*}
    Therefore $\frac{1}{n} \sum_{i=1}^n \flr{v_i \delta_{\nicefrac{1}{4}}}^{-1} > \min\left\{\nicefrac{n \varepsilon}{2 \sigma^2}, 1\right\},$ meaning $\bar{\delta} \geq \delta_{\nicefrac{1}{4}}.$
\end{proof}

{\EXAMPLETRENDHETER*}

{
\begin{proof}
  We have $V_i(t) = \int_{0}^{t} v_i g(\tau) d \tau = v_i G(t).$ We substitute this equality to \eqref{eq:upper_bound} and get
  $\bar{t}_k = \min\left\{t \geq 0 \, : \, \left(\frac{1}{n} \sum_{i=1}^n \flr{v_i \left(G(t) - G(\bar{t}_{k-1})\right)}^{-1}\right)^{-1} \geq \max\left\{\frac{2 \sigma^2}{n \varepsilon}, 1\right\}\right\}.$
  Since $G(t)$ is continuous and increasing, one can show that
    $\textstyle G(\bar{t}_k) = \min\left\{t \geq 0 \, : \, \left(\frac{1}{n} \sum_{i=1}^n \flr{v_i \left(t - G(\bar{t}_{k-1})\right)}^{-1}\right)^{-1} \geq \max\left\{\frac{2 \sigma^2}{n \varepsilon}, 1\right\}\right\}.$ Therefore $G(\bar{t}_k) = \bar{\delta} + G(\bar{t}_{k-1}) = k \bar{\delta}$ and $\bar{t}_k = G^{-1}(k \bar{\delta}),$ where $\bar{\delta}$ is defined in \eqref{eq:HerGofIi}. Using \eqref{eq:IzpJGassagPwg}, we get \eqref{eq:bwvFomtFlwGBlgeblrheter}.
\end{proof}
